4.주제 만들기: 모든 것 위에 뛰어난 하나님의 아들
5.하나님 찾기 (관찰)
- 옛적에 선지자를 통하여 말씀하신 하나님께서 마지막에는 아들을 통하여 말씀하심.
- 아들을 만유의 상속자로 세우시고 그로 말미암아 모든 세계를 지으심
- 아들은 하나님의 영광의 광채이고 본체의 형상이다.
- 아들은 말씀으로 만물을 보존하고 죄를 깨끗케 하시고 하나님의 우편에 앉으셨다.
- 하나님께서 천사나 선지자에게 말씀하신 것과 다르게 아들에게는 너는 내 아들이라 말씀하셨으며, 모든 천사들은 아들에게 경배하라고 말씀하심
- 땅도 하늘도 아들이 지으셨으며 창조물들은 멸망하지만 아들은 영존할 것임.
- 천사들은 섬기는 영으로서 구원받을 상속자들을 위하여 섬기라고 보내심
6.인간 찾기 (관찰)
7.하나님 찾기 (해석) 
- 예수님은 하나님의 아들이시며 하나님의 영광의 광채이시고, 하나님의 본체이시다.
- 예수님은 하나님의 아들로서 천사와 비교할 수 없는 분이시다.
- 예수님은 모든 천사에게 경배를 받는 분이시다.
- 예수님은 영원하신 분이다.
- 천사들은 섬기는 영으로 예수님과 예수님을 믿어 구원을 받는 그리스도인을 섬기라고 보내어진 존재들이다. 
