잠시 동안 천사보다 못한 사람들

7.하나님 찾기 (해석)
오늘 본문은 기자가 인간을 사랑하사 구원으로 이끄시는 과정에서 삼위일체 하나님을 모두 등장시켰다

우선 하나님에 대해서는 4절에 "표적들과 기사들과 여러 가지 능력과 및 자기의뜻" 에 대하여 기록 함으로써 전능하신 하나님의 속성을 보여주고 있다

성령님에 대해서는 증언자로써의 역활을 나타내고 있다

예수님에 대해서는 9절에 "하나님의 은혜로 말미암아 모든 사람을 위하여 죽음을 맛보려 하심이라 " 기록된바 크신 구원자요 창시자인것을 명확하게 보여주고 있다

반면 인간에 대해서는 죄로 인하여 죽을수밖에 없는 불쌍한 피조물인데 삼위일체 하나님이 모두 연합하시어 구원에 이르도록 하시는 사랑의 완성으로 이끄심을 알려주고 있다
"사람이 무엇이기에 주께서 그를 생각하며"


8.인간 찾기 (해석)

9. 적용(나)
크신  하나님의 사랑을 늘 생각하며 감사하는 마음으로 살아야겠다 

10. 영적 터치(단어/구절)
6절: 사람이 무엇이기에 주께서 그를 생각하시며

