4.주제 만들기: 믿음 없이는 하나님의 안식에 들어갈 수 없다 

5.하나님 찾기 (관찰)
- 내가 노하여 맹세한 바와 같이 그들은 내 안식에 들어오지 못하리라

6.인간 찾기 (관찰)
- 누가 믿지 아니하는 악한 마음을 품고 살아 계신 하나님에게서 떨어질까 조심할 것
- 누구든지 죄의 유혹으로 완고하게 되지 않도록 하라
- 시작할 때에 확신한 것을 끝까지 견고히 잡고 있으면 그리스도와 함께 참여한 자가 되리라

7.하나님 찾기 (해석)
- 하나님을 믿지 않으면 하나님의 안식에 들어갈 수가 없다. 

8.인간(해석): 
- 하나님을 믿지 않는 악한 마음을 품거나 
- 모세 당시 광야의 백성들처럼 마음이 완고해져서는 안 된다.
- 죄의 유혹에 빠지면 하나님 앞에서 완고하게 된다.
- 하나님을 처음 믿기로 했을 때 확신한 것을 끝까지 지켜야 한다.
- 믿음을 끝까지 지키면 그리스도께서 주시는 구원을 함께 받을 것이다.
- 모세 당시 광야의 백성들처럼 마음이 완고하여 범죄하고 순종하지 아니하면 구원받을 수 없다.

9. 적용(나): 
- 믿는 사람의 마음이 완고해질 수 있는가?
- 죄의 유혹에 빠지면 완고해질 수 있다.
- 죄를 짓는 것이 하나님께 순종하는 것보다 즐겁기 때문에,
- 그 즐거움을 위하여 하나님께 악한 마음을 품고 완고하게 되는 것이다.
- 그 즐거움을 위하여 범죄하고 하나님께 순종하지 않는 것이다.
- 이런 행동들은 하나님을 믿지 않는 것의 증거이다.
- 늘 하나님을 즐거워하며, 죄의 유혹에 빠지지 않도록 조심해야 한다.

