4.주제만들기: 하나님이 주시는 영적 안식
5.하나님 찾기 (관찰)
- 세상을 창조하시고 제칠일에 안식하심
6.인간 찾기 (관찰)
- 바울은 안식에 이를 기회가 있음에도 이를 누리지 못하는 자들이 있음을 말하였다.
- 바울은 복음을 먼저 받은 자들이 순종하지 못함으로 안식을 누리지 못했다고 말했다.
- 여호수아가 준 안식과는 다르며 이미 하나님의 안식에 들어간 자는 하나님이 자기의 일을 쉬심과 같이 자기의 일을 쉴 수 있다고 말했다.
7.하나님 찾기 (해석) 
- 하나님께선 하나님이 하실 일을 정확히 이루시고 안식을 취하셨다.
- 하나님께선 취하신 안식은 육신의 안식과 영의 안식을 모두 포함하고 있다. 
- 하나님께서 주시는 안식은 우리가 생각하는 안식과는 차원이 다르다.
8.인간(해석): 
- 하나님을 믿는다고 말하는 사람들이 안식에 들어가지 못하는 이유는(나를 포함하여) 믿음이 부족하기 때문이다. 믿음이 부족하다는 말에 시험에 들 수 있지만 이 말은 나의 현재 상황에서 걱정으로 평안하지 못한 모습을 보이는 나의 행동을 통해 알 수 있다. 이 말은 팩트이다. 
- 바울은 한 차원 높은 믿음의 성장을 요구하는 것 같다. 당시 상황에서 예수를 믿음으로 받아들이고 결단한 사람들이 성장하지 못하는 모습을 보며 안타까웠을 것이다. 현대 시대에 바울이 살고 있다면 어떤 생각을 할까? 종교의 제약이 없는 한국만 놓고 본다면 기가 찰 노릇일 것이다 
9. 적용(나): 
- 하나님이 주시는 안식에 들어갈 수 있도록 믿음을 굳건히 하여야 하는데 내가 할 수 있는 가장 쉬운 방법은 예배, 말씀, 기도이고 두 번째는 하나님의 일을 열심히, 최선을 다해하고 하나님을 의지하는 것이다. 어떠한 상황에도 일어설 수 있는 믿음을 주신 하나님을 더 의지하고 붙잡아야겠다.
10. 영적터치(단어/구절)
- 안식
