7.하나님 찾기 (해석)
큰 대제사장 이신 예수는 그의 성도들에게 긍휼을 베푸시고 특별히 믿음으로 따라오는 자들을 돕는 은혜를 주신다

그의 자녀들이 세상에서 다양한 시련과 시험을 당할때 결코 내버려두지 않으시고 끝까지 일으켜 세우시는 긍휼하신 주님 이시다

주님은 이땅에 육신으로 오셔서 인간이 최고로 느낄수  있는 수치와 아픔 그리고 고통을 몸소 체험하시므로 모든 인간들의 마음을 정확히 아시고 인간들을 정확히 위로하시기에 부족함이 없으시다

그러한 주님은 인간과 달리 죄가 전혀 으신 완전하신 하나님의 아들 이시다
8.인간 찾기 (해석)
인간의 모든 억울함과 고초를 아시는 주님을 믿고 따르는 태도야말로 성도의 기본적인 모습임을 기자는 기록하였다

때때로 성도 자신의 연약함이 있더라도 용기를 내어  주님의 은혜의 보좌앞에 담대히 나아가는 모습은 마치 아기가 어미를  향하여 다가가는 매우 자연스럽고 안정된 모습이라 볼수있다

9. 적용(나)
내 모습 비록 연약하고 부족함이 많이 있더라도 때마다 용서하시고 도우시는 주님을 향하여 더욱 담대히 나아가야겠다

