3.반복단어(같은의미 단어)
대제사장: 1, 5, 10
하나님: 1, 4, 10, 12
멜기세댁: 6, 10, 11
순종: 8, 9
단단한 음식: 12, 14 
젖: 12, 13
4. 주제 만들기: 멜기세댁의 서열을 따른 대제사장

5.하나님 찾기(관찰)
- 그가 아들이시면서도 받으신 고난으로 순종함을 배워 온전하게 되심
- 자기에게 순종하는 모든 자에게 영원한 구원의 근원이 되심
- 하나님께 멜기세덱의 반차를 따른 대제사장으로 칭해짐

6.인간 찾기(관찰)
- 대제사장마다 사람 가운데서 택한 자이므로 자기도 연약함.
- 그러므로 백성과 더불어 자신을 위하여도 속죄제를 드림
- 대제사장은 하나님의 부르심을 받은 자여야 함
- 시간으로 보면 선생이 되었어야 하는데 말씀의 초보에 대하여 누구에게서 가르침을 받아야 할 처지에 있음
- 단단한 음식은 못 먹고 젖이나 먹어야 할 자가 됨
- 이런 자는 어린 아이나 다름 없어 의의 말씀을 경험하지 못함
- 장성한 자는 선과 악을 분별하는 지각을 지님

7. 하나님 찾기(해석)
- 예수님은 하나님의 아들이시면서도 육신의 모양으로 내려오셔서 고난받으시고 십자가를 감당하심으로 온전하게 되심으로써 자신에게 순종하는 모든 자에게 영원한 구원의 근원이 되심. 
- 하나님께서 아론을 따르는 인간 대제사장이 아니라, 멜기세덱의 서열을 따른 대제사장으로 임명하심. 
- 멜기세댁의 서열을 따른다는 것은 인간 대제사장과는 다르게 예수님은 죄가 없으시며 단 한번의 제사로 믿는 모든 자에게 영원한 속죄를 이루신다는 것을 의미함.

8. 인간 찾기 (해석)
- 사람 가운데 택한 대제사장은 백성을 위해 속죄를 드리지만, 자신도 죄가 있음
- 자신도 죄가 있기에 자신을 위하여도 속죄제를 드려야 함.
- 복음을 들은 지 오래되어, 이제 선생이 되어야 할 사람들이 아직도 말씀의 초보에 대하여 가르침을 받아야 하는 사람들이 있음.
- 이런 사람들은 의의 말씀을 경험하지 못한 자이며, 옳은 일을 분별하기가 어려움
- 장성한 사람들은 경험이나 훈련을 통하여 선악을 분별하는 지각이 있음

9. 적용(나) 
- 멜기세댁의 반차를 따른 대제사장이신 예수님을 바라보아야 한다.
- 장성한 사람이 되어 의의 말씀을 경험함으로써 선악을 분별하는 지각을 지녀야 한다.

10. 영적 터치(단어/구절)
  14   단단한 음식은 장성한 자의 것이니 그들은 지각을 사용함으로 연단을 받아 선악을 분별하는 자들이니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-09', '히브리서', '6장 1절 ~ 10절', '신앙이 지속해서 성장해야 하는 이유.', '[히6:1-10]
1 그러므로 우리가 그리스도의 도의 초보를 버리고 죽은 행실을 회개함과 하나님께 대한 신앙과
2 세례들과 안수와 죽은 자의 부활과 영원한 심판에 관한 교훈의 터를 다시 닦지 말고 완전한 데로 나아갈지니라
3 하나님께서 허락하시면 우리가 이것을 하리라
4 한 번 빛을 받고 하늘의 은사를 맛보고 성령에 참여한 바 되고
5 하나님의 선한 말씀과 내세의 능력을 맛보고도
6 타락한 자들은 다시 새롭게 하여 회개하게 할 수 없나니 이는 그들이 하나님의 아들을 다시 십자가에 못 박아 드러내 놓고 욕되게 함이라
7 땅이 그 위에 자주 내리는 비를 흡수하여 밭 가는 자들이 쓰기에 합당한 채소를 내면 하나님께 복을 받고
8 만일 가시와 엉겅퀴를 내면 버림을 당하고 저주함에 가까워 그 마지막은 불사름이 되리라
9 사랑하는 자들아 우리가 이같이 말하나 너희에게는 이보다 더 좋은 것 곧 구원에 속한 것이 있음을 확신하노라
10 하나님은 불의하지 아니하사 너희 행위와 그의 이름을 위하여 나타낸 사랑으로 이미 성도를 섬긴 것과 이제도 섬기고 있는 것을 잊어버리지 아니하시느니라

