- 회개(1,6절), 섬기다(10절), 사랑(9,10절) 
4.주제만들기: 신앙이 지속해서 성장해야 하는 이유. 
5.하나님 찾기 (관찰)
- 하나님께서는 행위와 섬긴 것과 현재도 섬기는 것을 잊지 않으신다.
6.인간 찾기 (관찰)
- 바울은 초보적인 신앙에서 영적 성장을 이루길 권면한다.
- 바울은 특히 믿음을 가진 자들이 무너졌을 때 위험성을 경고하며 다시 회복하기 어렵다는 사실을 알려주었다.
- 바울은 받아들이는 사람에 따라 좋은 채소를 내거나 엉겅퀴와 같이 버림 받은 땅이 될 수 있다고 말한다.
- 바울은 하나님께서 우리의 행위를 보고 계시며 잊지 않으신다고 말하였다.
7.하나님 찾기 (해석) 
- 하나님께서는 우리의 사역을 현재도 지켜보고 계신다. 정체된 듯한 NKFC 사역이 하나님의 뜻일 수도 있고, 테스트일 수도 있다. 하지만 명백한 사실은 하나님께서 보고 계시다는 것이다. 최선을 다한 후에 하나님의 뜻을 살피는 것이 맞다
8.인간(해석):
- 바울은 신앙의 성장을 계속해서 강조하고 있다. 초보적인 신앙은 좋은 밭이 되기 전에 본래의 땅으로 돌아갈 수 있는 연약함을 가지고 있다. 신앙의 성장은 좋은 밭이 되어 비가 내리든 내리지 않든, 좋은 땅임을 알기에 버틸 수 있는 토대가 있다.
- 믿음을 가졌던 자들이 믿음을 잃었을 때 심각성은 하나님을 알지 못하는 자들이 하는 행위보다 더 심각함을 깨닫는다. 경건함에 이르기까지 수많은 어려움이 있기 때문에 그 과정을 버티지 못한다면 최악의 결과를 가져올 수 있다. 
- 하나님께서 주시는 분명한 메시지는 신앙의 성장을 이루라는 것이다.
9. 적용(나): 
- 예배, 말씀, 기도를 기본으로 하고 전도, 구제, 선교의 삶을 평생 살아가길 기도한다.
- NKFC 사역에 최선을 다하자.
10. 영적터치(단어/구절)
- 10 하나님은 불의하지 아니하사 너희 행위와 그의 이름을 위하여 나타낸 사랑으로 이미 성도를 섬긴 것과 이제도 섬기고 있는 것을 잊어버리지 아니하시느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-10', '히브리서', '6장 11절 ~ 20절', '제목 없음', '(히브리서 6장)
11. 우리가 간절히 원하는 것은 너희 각 사람이 동일한 부지런함을 나타내어 끝까지 소망의 풍성함에 이르러
12. 게으르지 아니하고 믿음과 오래 참음으로 말미암아 약속들을 기업으로 받는 자들을 본받는 자 되게 하려는 것이니라
13.  하나님이 아브라함에게 약속하실 때에 가리켜 맹세할 자가 자기보다 더 큰 이가 없으므로 자기를 가리켜 맹세하여
14. 이르시되 내가 반드시 너에게 복 주고 복 주며 너를 번성하게 하고 번성하게 하리라 하셨더니
15. 그가 이같이 오래 참아 약속을 받았느니라
16. 사람들은 자기보다 더 큰 자를 가리켜 맹세하나니 맹세는 그들이 다투는 모든 일의 최후 확정이니라
17. 하나님은 약속을 기업으로 받는 자들에게 그 뜻이 변하지 아니함을 충분히 나타내시려고 그 일을 맹세로 보증하셨나니
18. 이는 하나님이 거짓말을 하실 수 없는 이 두 가지 변하지 못할 사실로 말미암아 앞에 있는 소망을 얻으려고 피난처를 찾은 우리에게 큰 안위를 받게 하려 하심이라
19. 우리가 이 소망을 가지고 있는 것은 영혼의 닻 같아서 튼튼하고 견고하여 휘장 안에 들어 가나니
20. 그리로 앞서 가신 예수께서 멜기세덱의 반차를 따라 영원히 대제사장이 되어 우리를 위하여 들어 가셨느니라

