4.주제만들기: 반드시 이루어지는 맹세의 말씀
5.하나님 찾기 (관찰)
- 언약의 보증이 되심
- 영원히 계시므로 제사장 직분이 사라지지 않음
- 하나님께 나아가는 자들을 구원하시며 항상 살아계셔서 우리를 위하여 간구하심
- 거룩하고 악이 없으며 더러움이 없고 죄인에게서 떠나계시며 하늘보다 높이 되심
- 인간의 죄를 위하여 자신을 드려 인간의 제사를 없애심
- 맹세의 말씀으로 영원히 온전하게 하실 자신의 아들을 대제사장으로 세우심 
6.인간 찾기 (관찰)
- 맹세 없이 대제사장이 되었던 인간들
- 인간은 죽음으로 인해 대제사장의 역할을 영원히 하지 못함
- 대제사장은 하나님께 제사를 드리기 위해 먼저 자신의 죄를 위해 기도한 후에야 백성의 죄를 위해 기도함  
7.하나님 찾기 (해석) 
- 무한한 인간의 연약함을 뛰어넘는 유한한 하나님의 구원 계획과 사랑은 어느 누구에게나 언제 어디서든 구원을 받을 수 있는 은혜를 허락하셨다.
- 인간은 온전하지 못한 연약함이 있으나 완전하신 예수님으로 인해 인간의 허물을 덮어주셨다. 예수님의 십자가 사랑과 희생은 전적인 하나님의 계획으로 영원토록 우리의 보증자가 되셨으며, 우리를 위해 간구하시는 중보자가 되셨다.
- 율법이 가진 한계를 뛰어넘기 위해 하나님의 맹세의 말씀으로 완전하고 영원한 아들을 제사장으로 세워주셨다. 이는 율법의 한계를 극복하게 된다.
8.인간(해석):
- 인간의 율법에 얽매여있는 연약한 존재이다. 인간이 맡은 대제사장은 자신의 죄를 위해 기도한 후에야 백성을 위해 기도할 수 있다. 이는 인간은 완전한 존재가 될 수 없음을 의미한다.
- 예수님의 구원과 사랑, 영원한 간구로 우리를 붙들어주셨다. 우리의 중보자로서 우리를 지켜주시고 보호하고 계신다. 그분의 사랑을 깨닫고 있다면 현재의 삶을 두려워할 이유가 없다.  
9. 적용(나): 
- 나의 영원한 중보자 예수님을 의지하며 감사하며 그 분의 세밀한 음성에 귀기울이는 삶을 살아야겠다. 
- 흠 없는 예수님의 십자가 사랑으로 죄 많은 내가 구원 받았음을 감사하며, 예수님을 닮아가는 하루를 매일 실천하고 싶다.
- 예수님의 사랑은 우리의 죄를 자유케한다. 반복되는 죄악도 반드시 끊어질 것을 확신한다.
10. 영적터치(단어/구절)
- 25 그러므로 자기를 힘입어 하나님께 나아가는 자들을 온전히 구원하실 수 있으니 이는 그가 항상 살아 계셔서 그들을 위하여 간구하심이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-14', '히브리서', '8장 1절 ~ 13절', '더 좋은 약속을 하시는 하나님', '[히8:1-13]
1 이제 하는 말의 중요한 것은 이러한 대제사장이 우리에게 있는 것이라 그가 하늘에서 위엄의 보좌 우편에 앉으셨으니
2 성소와 참장막에 부리는 자라 이 장막은 주께서 베푸신 것이요 사람이 한 것이 아니니라
3 대제사장마다 예물과 제사 드림을 위하여 세운 자니 이러므로 저도 무슨 드릴 것이 있어야 할찌니라
4 예수께서 만일 땅에 계셨더면 제사장이 되지 아니하셨을 것이니 이는 율법을 좇아 예물을 드리는 제사장이 있음이라
5 저희가 섬기는 것은 하늘에 있는 것의 모형과 그림자라 모세가 장막을 지으려 할 때에 지시하심을 얻음과 같으니 가라사대 삼가 모든 것을 산에서 네게 보이던 본을 좇아 지으라 하셨느니라
6 그러나 이제 그가 더 아름다운 직분을 얻으셨으니 이는 더 좋은 약속으로 세우신 더 좋은 언약의 중보시라
7 저 첫 언약이 무흠하였더면 둘째 것을 요구할 일이 없었으려니와
8 저희를 허물하여 일렀으되 주께서 가라사대 볼찌어다 날이 이르리니 내가 이스라엘 집과 유다 집으로 새 언약을 세우리라
9 또 주께서 가라사대 내가 저희 열조들의 손을 잡고 애굽 땅에서 인도하여 내던 날에 저희와 세운 언약과 같지 아니하도다 저희는 내 언약 안에 머물러 있지 아니하므로 내가 저희를 돌아보지 아니하였노라
10 또 주께서 가라사대 그 날 후에 내가 이스라엘 집으로 세울 언약이 이것이니 내 법을 저희 생각에 두고 저희 마음에 이것을 기록하리라 나는 저희에게 하나님이 되고 저희는 내게 백성이 되리라
11 또 각각 자기 나라 사람과 각각 자기 형제를 가르쳐 이르기를 주를 알라 하지 아니할 것은 저희가 작은 자로부터 큰 자까지 다 나를 앎이니라
12 내가 저희 불의를 긍휼히 여기고 저희 죄를 다시 기억하지 아니하리라 하셨느니라
13 새 언약이라 말씀하셨으매 첫것은 낡아지게 하신 것이니 낡아지고 쇠하는 것은 없어져가는 것이니라

