INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-16', '히브리서', '9장 11절 ~ 20절', '그리스도의 보혈의 피로 부르심과 영원한 기업을 받은 우리', '[히9:11-20]
11 그리스도께서는 장래 좋은 일의 대제사장으로 오사 손으로 짓지 아니한 것 곧 이 창조에 속하지 아니한 더 크고 온전한 장막으로 말미암아
12 염소와 송아지의 피로 하지 아니하고 오직 자기의 피로 영원한 속죄를 이루사 단번에 성소에 들어가셨느니라
13 염소와 황소의 피와 및 암송아지의 재를 부정한 자에게 뿌려 그 육체를 정결하게 하여 거룩하게 하거든
14 하물며 영원하신 성령으로 말미암아 흠 없는 자기를 하나님께 드린 그리스도의 피가 어찌 너희 양심을 죽은 행실에서 깨끗하게 하고 살아 계신 하나님을 섬기게 하지 못하겠느냐
15 이로 말미암아 그는 새 언약의 중보자시니 이는 첫 언약 때에 범한 죄에서 속량하려고 죽으사 부르심을 입은 자로 하여금 영원한 기업의 약속을 얻게 하려 하심이라
16 유언은 유언한 자가 죽어야 되나니
17 유언은 그 사람이 죽은 후에야 유효한즉 유언한 자가 살아 있는 동안에는 효력이 없느니라
18 이러므로 첫 언약도 피 없이 세운 것이 아니니
19 모세가 율법대로 모든 계명을 온 백성에게 말한 후에 송아지와 염소의 피 및 물과 붉은 양털과 우슬초를 취하여 그 두루마리와 온 백성에게 뿌리며
20 이르되 이는 하나님이 너희에게 명하신 언약의 피라 하고

