2024년 4월 19일 히브리서 9장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 피(12,13,14,18,19,20절), 염소(12,13,19절), 소(12,13,19절), 언약(15절), 유언(16,17,20절), 뿌리다(13,19절)
4.주제만들기: 그리스도의 보혈의 피로 부르심과 영원한 기업을 받은 우리
5.하나님 찾기 (관찰)
- 그리스도께서 장래 좋은 일의 대제사장으로 오심
- 오직 자신의 피로 영원한 속죄를 이루심
- 성령으로 말미암아 흠 없는 자신을 하나님께 드리심
- 새 언약의 중보자, 첫 언약 때에 범한 죄를 속량하심
6.인간 찾기 (관찰)
- 부르심을 입은 우리는 영원한 기업의 약속도 받게 됨
7.하나님 찾기 (해석) 
- 하나님께서는 육체의 몸으로 우리의 죄를 대속하기 위해 십자가 피 흘리심을 통해 성소로 들어가셨다. 과거 속죄를 위한 의식 중 염소와 항소의 피와 암송아지의 재를 부정한자에게 뿌져 육체를 정결케 하였는데 그 모든 것을 타파하시고 오직 예수님의 피로 우리를 깨끗게 해주신 것이다.
- 값 없이 받는 것은 소중히 여기지 않는 것이 인간의 본성 마냥 우리는 전적인 은혜로 하나님을 믿지만 반복된 죄에서 벗어나지 못한다. 예수님의 사랑을 진정으로 안다면 나의 행동은 변화되어야 하지만 그렇지 못한다. 그럼에도 우리를 사랑하시고 끝까지 보호하여 주신다.
- 하나님은 하나님 자신이 이 땅에 내려오셔서 연약한 육체로 완전함을 이루셨다. 그러기 위해서 수 많은 고통을 모두 감내하셨다. 우리 하나님은 그러신 분이다. 이 세상 유일하신 완전하신 분. 
8.인간(해석):
- 염소와 황소의 피, 암송아지의 재는 인간이 죄를 짓는 것을 막아주는 수단은 되었을 것이다. 그러나 이런 의식은 번거로움이 따르며 수많은 세월을 지나 변형되고 사라졌을 것이다. 
- 나의 모습도 동일하다. 예수님을 사랑하는 마음과 간절함, 예수님을 만나고 싶은 하루를 몇일이나 살고 있는지 모르겠다.
- 하지만 하나님은 우리를 위해 부르셨고 부르신 것에서 끝나는 것이 아니라 영원한 기업을 약속해주셨다. 끝없는 하나님의 사랑을 느낄 수 있다. 
9. 적용(나): 
- 하나님을 믿는 다는 것을 당연하게 생각할 때가 있다. 그리고 맡기신 사명이 막힐 때 그것에 대한 노력은 하지 않고 하나님의 뜻이 아니라 단정 지을 때가 있다. 하나님께서 베푸신 은혜와 사랑을 기억하며 모든 일에 최선을 다하고 기도해야겠다.
- 하나님께서 부르신 것과 영원한 기업을 받은 것을 많은 사람들이 알았으면 좋겠다. 그 분의 은혜를 많은 사람이 누렸으면 좋겠다. 노방전도를 얼른 나가고 싶다.
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

