5.하나님 찾기 (관찰)
- 예수님이 그리스도인을 한 번의 제사로 영원히 온전하게 하심
- 하나님의 법을 그리스도인들의 마음에 두고 생각에 기록하리라고 말씀하심
- 그리스도인들의 죄와 불법을 다시 기억하지 아니하리라 말씀하심
- 예수님이 휘장 가운데로 새로운 살 길을 열어놓으셨는데, 그 휘장은 예수님의 육체이다

6.인간 찾기 (관찰)
- 제사장이 매일 제사를 드려도 죄를 없애지는 못함
- 예수님이 한 번의 제사로 죄를 사하셨은즉 다시 죄를 위하여 제사드릴 것이 없음
- 예수의 피를 힘입어 성소에 들어갈 담력을 얻었음

7.하나님 찾기 (해석) 
- 예수님이 십자가에 달려 죽으심으로 단 한 번의 제사로 모든 죄를 사하셨고,
- 인간이 할 수 없는 죄로부터의 해방이 그리스도인에게 성취됨 
- 하나님께서 인간의 모든 죄와 불법을 기억하지 않겠다고 하심
- 예수님의 십자가 사역은 지성소를 막아 놓은 휘장을 꿰뚫는 사역이기 때문에 우리가 담대히 지성소에 들어갈 수 있음
- 예수님의 십자가는 우리를 죄에서 해방시켰을뿐 아니라 하나님과 우리를 갈라놓았던 휘장을 찢어, 그리스도인이 하나님께 담대히 나아갈 수 있게 만들었음 

8.인간(해석): 
- 예수님의 은혜로 그리스도인은 죄를 영원히 사함 받게 됨
- 예수님의 은혜로 그리스도인은 하나님 앞에 담대히 나아가 예배할 수 있게 됨

9. 적용(나): 
- 예수님의 은혜를 기억하고, 죄가 많으나 죄 사함 받은 것을 늘 기억하고,
- 예수님이 열어주신 새로운 살 길에 매일 나아가
- 감사와 찬송함으로 하나님을 예배해야겠다.

