2024년 4월 23일 히브리서 10장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 갚다(30절), 마음(22,27절),
4.주제만들기: 오직 예수님만 의지하며 붙잡아야 할 소망
5.하나님 찾기 (관찰)
- 하나님의 집을 다스리시는 대제사장이 되신 예수
- 그의 백성을 심판하리라 말씀하심
6.인간 찾기 (관찰)
- 바울은 예수님으로 인해 악한 양심에서 벗어나고 맑은 물로 씻음을 받았으니 참 마음과 온전한 믿음으로 하나님께 나가자고 말함
- 믿음을 잃지 말고 소망을 굳게 잡아 서로 돌아보고 사랑과 격려를 하라고 권함
- 하나님의 아들을 짓밟고 언약의 피를 보정한 자들과 성령을 욕되게 하는 자들의 형벌은 얼마나 무거울지 생각하라고 말함.
7.하나님 찾기 (해석) 
- 죄 많은 우리가 예수님의 십자가 사랑으로 죄사함을 얻게 됨.
8.인간(해석):
- 당시 시대에서 하나님을 믿고 소망을 바라보며 사는 것은 현대 사회보다 더 어려울 것이다. 그리스도를 믿는 자들을 핍박하고 희롱하는 일들이 빈번한 때에 믿음을 지키는 일은 쉽지 않았을 것이다. 그리고 현대처럼 믿음을 벗어나면 인간이 느낄 수 있는 흥미로운 일들이 많기 때문에 다시 사신 예수님을 생각하며 믿음을 붙잡는 일은 쉽지 앟ㄴ았을 것 같다.
- 현대에도 마찬가지이다. 일주일에 2~3일을 교회에 가는 것, 주일에 교회에만 있는 것 등은 현대 사람들에게 쉽게 납득되지 않는 행동 따위로 여겨지고 있다. 이런 환경과 문화는 현대에 사는 크리스천들에게 오히려 기회(?)일 수도 있다. 예전처럼 핍박 받으며 사역할 일은 적지만 적어도 예수님을 전한다는 것은 과거나 이 시대나 쉬운 일은 아니었을 것이다. 그럼에도 우리를 위해 십자가에 매달리신 주님을 생각하며 그분을 전하는 일을 게을리해서는 안된다. 
9. 적용(나):
- 먼저 그의 나라와 그의 의를 구하는 일을 최우선으로 여기는 가정이 되길 기도한다.
- 이를 위해 솔선수범하는 아빠가 되어야겠다. 
10. 영적터치(단어/구절)
- 소망을 움직이지 말며 굳게 잡고
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-21', '히브리서', '10장 31절 ~ 39절', '오직 영혼구원', '[히10:31-39]
31 살아계신 하나님의 손에 빠져 들어가는 것이 무서울진저
32 전날에 너희가 빛을 받은 후에 고난의 큰 싸움에 참은 것을 생각하라
33 혹 비방과 환난으로써 사람에게 구경거리가 되고 혹 이런 형편에 있는 자들로 사귀는 자 되었으니
34 너희가 갇힌 자를 동정하고 너희 산업을 빼앗기는 것도 기쁘게 당한 것은 더 낫고 영구한 산업이 있는줄 앎이라
35 그러므로 너희 담대함을 버리지 말라 이것이 큰 상을 얻느니라
36 너희에게 인내가 필요함은 너희가 하나님의 뜻을 행한 후에 약속을 받기 위함이라
37 잠시 잠깐 후면 오실 이가 오시리니 지체하지 아니하시리라
38 오직 나의 의인은 믿음으로 말미암아 살리라 또한 뒤로 물러가면 내 마음이 저를 기뻐하지 아니하리라 하셨느니라
39 우리는 뒤로 물러가 침륜에 빠질 자가 아니요 오직 영혼을 구원함에 이르는 믿음을 가진 자니라

