-고난의 큰 싸움을 참은 자
-비방과 환난으로써 사람에게 구경거리 된 자
-이런 형편에 있는 자와 사귀는 자
-갇힌 자를 동정하는 자
-오직 영혼 구원함에 이르는 믿음을 가진 자
