원하시는 하나님
8.인간(해석):
-하나님의 일에 동참하는 건 어려운 일이다. 어렵다고 동참하지 않고 하나님과의 관계가 멀어진다면 하나님과의 약속을 깨버리는 것. 큰 시련을 당하고도 믿음을 지킬 수 있었던 것은 하나님을 얼마나 사랑하고 생각하는지 그리고 그런 자들에게 하나님께서도 얼마나 큰 은혜를 부어주시는지 느끼게 된다. 
9.적용(나):
-얼마전 조재필 목사님은 노방전도를 하나님께서 크게 기뻐하신다는 은혜를 받았던 것을 나눠주셨다. 말씀 안에서도 오직 영혼 구원이란 말씀을 나눠주셨다. 주님께서 가장 기뻐하시는 것, 나도 가장 기뻐하는 일이 영혼 구원함이라는 것을 깨닫길 소망한다. 그 전에 주님 안에서 담대하고 인내하는 훈련을 잘 받아야겠다..
10. 영적터치(단어/구절)
-오직 영혼을 구원함에 이르는 믿음을 가진 자니라
