INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-22', '히브리서', '11장 1절 ~ 10절', '제목 없음', '2024년 4월 25일 히브리서 11장 1~10절

1   믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거니
2   선진들이 이로써 증거를 얻었느니라
3   믿음으로 모든 세계가 하나님의 말씀으로 지어진 줄을 우리가 아나니 보이는 것은 나타난 것으로 말미암아 된 것이 아니니라
4   믿음으로 아벨은 가인보다 더 나은 제사를 하나님께 드림으로 의로운 자라 하시는 증거를 얻었으니 하나님이 그 예물에 대하여 증언하심이라 그가 죽었으나 그 믿음으로써 지금도 말하느니라
5   믿음으로 에녹은 죽음을 보지 않고 옮겨졌으니 하나님이 그를 옮기심으로 다시 보이지 아니하였느니라 그는 옮겨지기 전에 하나님을 기쁘시게 하는 자라 하는 증거를 받았느니라
6   믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라
7   믿음으로 노아는 아직 보이지 않는 일에 경고하심을 받아 경외함으로 방주를 준비하여 그 집을 구원하였으니 이로 말미암아 세상을 정죄하고 믿음을 따르는 의의 상속자가 되었느니라
8   믿음으로 아브라함은 부르심을 받았을 때에 순종하여 장래의 유업으로 받을 땅에 나아갈새 갈 바를 알지 못하고 나아갔으며
9   믿음으로 그가 이방의 땅에 있는 것 같이 약속의 땅에 거류하여 동일한 약속을 유업으로 함께 받은 이삭 및 야곱과 더불어 장막에 거하였으니
10   이는 그가 하나님이 계획하시고 지으실 터가 있는 성을 바랐음이라

주제: 믿음과 삶

하나님 찾기 (관찰)
- 모든 세계가 하나님의 말씀으로 지어짐
- 아벨을 의로운 자라 하심
- 에녹을 옮기심
- 에녹은 하나님을 기쁘시게 하는 자라고 하심
- 믿음이 없이는 하나님을 기쁘시게 할 수 없음
- 노아에게 방주를 준비하게 하시고 의의 상속자로 세우심
- 아브라함을 부르시고 약속의 땅으로 보내심
- 하나님은 계획하시고 지으실 터가 있음

인간 찾기 (관찰)
- 선진들이 믿음으로 증거를 얻음
- 믿음으로 세상이 하나님의 말씀으로 지어진 줄을 아는 것임 
- 믿음으로 아벨은 가인보다 더 나은 제사를 하나님께 드림
- 아벨은 의로운 자라하는 증거를 얻음
- 믿음으로 에녹은 죽지 않고 옮겨짐
- 에녹은 하나님을 기쁘시게 하는 자라 하는 증거를 받았음
- 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 함
- 믿음으로 노아는 아직 보이지 않는 일에 경고하심을 받아 경외함으로 방주를 준비하여 그 집을 구원함
- 노아는 이 일로 믿음을 따르는 의의 상속자가 됨
- 믿음으로 아브라함은 부르심을 받았을 때 순종하여 갈 바를 알지 못하지만 나아감
- 믿음으로 이방 땅에 있는 것은 약속의 땅에 거류하며, 동일한 약속을 유업으로 받은 이삭 및 야곱과 더불어 장막에 거함
- 이것은 하나님이 계획하시고 지으실 터가 있는 성을 바란 것임

하나님 찾기 (해석) 
- 하나님은 스스로 계시는 유일한 하나님이시다
- 하나님은 이것을 믿는 믿음을 가진 자를 의롭다 하신다.
- 믿음이 있는 자의 믿음의 행위에 기뻐하신다

인간(해석): 
- 인간은 보이고, 들려지고, 냄새가 맡아지고, 맛이 나고, 만져지는 것 즉, 물질을 사실로 받아들인다.
- 또한 자신의 가치관과 세계관, 욕구에 부합되는 것을 믿고 싶어한다.
- 그러나 믿음은 보이는 것이기에, 내 입맛에 맞기에 믿는 그런 것이 아니다. 
- 믿음은 하나님이 하나님 되심을 믿는 것이다. 그러니 온 세상을 하나님이 창조하셨다는 보이지 않는, 내가 경험하지 못한 말씀을 믿는 것이다. 
- 왜냐하면 하나님은 스스로 계시는 여호와. 유일한 하나님이심을 믿기 때문이다. 
- 이것이 믿음이다.
- 연속해서 나오는 믿음의 조상들 아벨, 에녹, 노아, 아브라함 등은 이 믿음을 가져 하나님을 경외했기에, 
- 하나님의 말씀과 부르심에 순종했고, 
- 말씀하신 것이 보이지 않아도 믿음으로 행한 것이다. 

적용(나): 
- 하나님께서 유일하신 신이시오. 
- 온 세상을, 시간과 공간, 모든 존재하는 것을 창조하셨음을 믿는다.
- 그 하나님을 믿는 믿음을 주심에 감사하며,
- 믿는 자로서 주님의 말씀을 믿음으로 받고, 순종하는 삶을 살아야겠다. 


영적터치(단어/구절)  
3   믿음으로 모든 세계가 하나님의 말씀으로 지어진 줄을 우리가 아나니', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-23', '히브리서', '11장 11절 ~ 20절', '믿음을 잃지 않는 자들이 받은 축복', '[히11:11-20]
11 믿음으로 사라 자신도 나이가 많아 단산하였으나 잉태할 수 있는 힘을 얻었으니 이는 약속하신 이를 미쁘신 줄 알았음이라
12 이러므로 죽은 자와 같은 한 사람으로 말미암아 하늘의 허다한 별과 또 해변의 무수한 모래와 같이 많은 후손이 생육하였느니라
13 이 사람들은 다 믿음을 따라 죽었으며 약속을 받지 못하였으되 그것들을 멀리서 보고 환영하며 또 땅에서는 외국인과 나그네임을 증언하였으니
14 그들이 이같이 말하는 것은 자기들이 본향 찾는 자임을 나타냄이라
15 그들이 나온 바 본향을 생각하였더라면 돌아갈 기회가 있었으려니와
16 그들이 이제는 더 나은 본향을 사모하니 곧 하늘에 있는 것이라 이러므로 하나님이 그들의 하나님이라 일컬음 받으심을 부끄러워하지 아니하시고 그들을 위하여 한 성을 예비하셨느니라
17 아브라함은 시험을 받을 때에 믿음으로 이삭을 드렸으니 그는 약속들을 받은 자로되 그 외아들을 드렸느니라
18 그에게 이미 말씀하시기를 네 자손이라 칭할 자는 이삭으로 말미암으리라 하셨으니
19 그가 하나님이 능히 이삭을 죽은 자 가운데서 다시 살리실 줄로 생각한지라 비유컨대 그를 죽은 자 가운데서 도로 받은 것이니라
20 믿음으로 이삭은 장차 있을 일에 대하여 야곱과 에서에게 축복하였으며

