2024년 4월 27일 히브리서 11장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 믿음(11,13,17,20절), 본향(14,15,16절), 약속(11,13,17절), 이삭(17,18,19,20절)
4.주제만들기: 믿음을 잃지 않는 자들이 받은 축복
5.하나님 찾기 (관찰)
- 단산한 사라에게 자녀를 낳는다고 말하심
- 하늘의 별과 모래 같이 번성할 것이라고 말하심
- 아브라함에게 네 자손이라 칭할 자는 이삭으로 말미암으리라 말하심 
6.인간 찾기 (관찰)
- 사라는 단산의 과정에서도 하나님의 말씀으로 힘을 얻고 믿음
- 죽은자와 같던 한 사람으로 인해 많은 후손이 생육함
- 아브라함은 시험의 때에 믿음으로 이삭을 드림
7.하나님 찾기 (해석) 
- 하나님은 인간이 상상할 수 없는 방법으로 이끄시고 돕는 분이시다. 하나님께선 믿음을 매두 중요하게 생각하시는데 때로는 인간의 한계를 뛰어넘는 믿음을 요구하실 때가 있다. 
- 우리의 한계를 인정하고 믿음으로 순종했을 때 하나님께선 넘치는 복을 주신다. 우리가 하나님을 뜻을 쉽게 깨달으면 좋겠지만 하나님의 섭리를 알 수 없기 때문에 그저 믿음으로 순종하는 수 밖에 없다.
8.인간(해석):
- 하나님께선 우리에게 복 주시길 원하신다. 사라는 고령의 나이에 자녀를 가지리라는 하나님의 말씀을 신뢰하지 않고 비웃었다. 하지만 하나님의 언약을 믿어 자녀를 출산하였다. 하나님을 믿는다고 하지만 인간의 한계를 넘어서는 일에 하나님을 신뢰하는 믿음을 갖는 일은 하나님의 은혜와 강한 의지가 필요한 것 같다.
- 사라의 믿음은 죽은 자와 같은 인간으로부터 수많은 후손을 낳는 복으로 이어졌다.
- 아브라함은 이삭을 하나님께 드리며 죽은 자도 살릴 수 있다는 믿음을 가졌다. 아브라함의 순종으로 인간이 아닌 하나님이 자신을 제물로 드려 인간의 죄를 용서하여 주셨다. 
- 하나님께서 우리에게 원하시는 것은 믿음이다. 우리가 하나님을 믿는 순간 하나님은 우리의 생각을 초월하여 복을 주신다.
9. 적용(나): 
- 나의 한계를 넘어서는 믿음이 생길 수 있길 간절히 기도한다. 하나님의 은혜로 내 안에 하나님을 믿는 믿음이 가득 넘치길 소망한다.
- 하나님께 순종하며 하나님이 이끄시는 삶을 살아야겠다. 하나님의 은혜를 구한다.
10. 영적터치(단어/구절)
- 믿음
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-24', '히브리서', '11장 21절 ~ 30절', '', '(히브리서 11장)
21. 믿음으로 야곱은 죽을 때에 요셉의 각 아들에게 축복하고 그 지팡이 머리에 의지하여 경배하였으며
22. 믿음으로 요셉은 임종시에 이스라엘 자손들이 떠날 것을 말하고 또 자기 뼈를 위하여 명하였으며
23. 믿음으로 모세가 났을 때에 그 부모가 아름다운 아이임을 보고 석 달 동안 숨겨 왕의 명령을 무서워하지 아니하였으며
24. 믿음으로 모세는 장성하여 바로의 공주의 아들이라 칭함 받기를 거절하고
25. 도리어 하나님의 백성과 함께 고난 받기를 잠시 죄악의 낙을 누리는 것보다 더 좋아하고
26. 그리스도를 위하여 받는 수모를 애굽의 모든 보화보다 더 큰 재물로 여겼으니 이는 상 주심을 바라봄이라
27. 믿음으로 애굽을 떠나 왕의 노함을 무서워하지 아니하고 곧 보이지 아니하는 자를 보는 것 같이 하여 참았으며
28. 믿음으로 유월절과 피 뿌리는 예식을 정하였으니 이는 장자를 멸하는 자로 그들을 건드리지 않게 하려 한 것이며
29. 믿음으로 그들은 홍해를 육지 같이 건넜으나 애굽 사람들은 이것을 시험하다가 빠져 죽었으며
30. 믿음으로 칠 일 동안 여리고를 도니 성이 무너졌으며

