믿음으로 더 좋은 것을 선택한 자들

5.하나님 찾기 (관찰): 

6.인간 찾기 (관찰)
믿음으로 야곱은 죽을 때에 요셉의 각 아들에게 축복함.
믿음으로 요셉은 임종시에 이스라엘 자손들이 떠날 것을 말함.
모세는 믿음으로 바로의 공주의 아들보다 하나님의 백성과 함께 고난 받기를 더 좋아함.
믿음으로 홍해를 건너감.
믿음으로 칠 일 동안 여리고를 돔.

7.하나님 찾기 (해석)
세상에서 주는 즐거움을 따르는 것보다 힘들어도 하나님의 이끄시는 대로 순종하는 백성들에게 하나님은 반드시 더 크고 좋은 것으로 채워주신다.

8.인간(해석):
당시 강력한 국가인 애굽의 공주 아들로 자라며 부귀영화를 누릴수 있었던 모세는 모든것을 내려놓고 믿음으로 스스로 고난의 길 을 선택하였다.

그 고난의 길을 션택한 모세는 왕궁에서 느낄수 없었던 여호와 하나님 으로 부터 오는 영적 임제를 체험하는 삶을 살았다

믿음으로 하나님께 순종하는 성도들은 인생을 두렵게 하는 홍해를 가르며 고난의 장벽인 여리고 성 을 무너뜨릴수 있음을 보여준다

9.적용(나):
오늘은 오랜만에 야외에서 남북청년 연합 바비큐 파티와  풋살 경기를 갖는다. 이러한 작은 남북청년 모임이  확산되어 믿음으로 북한땅에도 복음의 교제가 이루어지기를 기도한다

