2024년 4월 28일 히브리서 11장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
믿음: 31절 33절 39절
세상이 감당하지 못하는 믿음:
35절 37절
환난/ 학대/조롱/결박/심한 고문:
35절 36절 37절 38절
하며: 33절(2) 34절(3) 35절 

4.주제만들기: 
세상이 감당하지 못하는 믿음

5.하나님 찾기 (관찰): 
우리를 위하여 더 좋은 것을 예비하심

6.인간 찾기 (관찰)
세상이 감당하지 못하는 믿음:
고문을 받되 구차히 풀려나기를 원하지 않음
잔혹한 죽임 앞에서 타협을 하지 않음

7.하나님 찾기 (해석)
세상을 이길수 있는 믿음은 인간 스스로가 만들어 내는것이 아니라 전적으로 하나님이 허락하실때 가능하다. 그것이 하나님의 은혜이다

비록 세상의 관점에서 보면 갖은 핍박과  고난 그리고 죽임을 당하는 그저 힘 없는 실패자 처럼 여겨질수 있으나 이 세상과 비교할수 없는 더 좋은 곳을 예비하신 역전의  하나님을 느낄수 있다

8.인간(해석):
기자가 시간이 부족하고 이름을 다 나열하기 어려울정도로 많은 믿음의 사람들이 있었음을 일깨워주고 있다

나열된 사람중에는 다윗과 삼손도 기록되어 있다. 특별히 삼손은 이방여인 데릴라 로 인하여 신앙에서 멀어지고 죽기전에 간신히 회개한 인물이다.
회개한후 명예는 회복됐지만 적군과 함께 비참한 죽음을 맞이했음에도 기록된것을 보면 저자의 하나님에 대한 성품을 알리기 위함 이라 느낄수 있다.
이를 통하여 크신 하나님의 인내하심과 자비하심이 있음을 선명하게 보여주고 있다.

39절 이하 "이 사람들은 다 믿음으로 말미암아 증거를 받았으나 약속된 것을 받지 못하였으니" 로 기록된겻으로 보았을때는 진정한 소망의 열매는 이생이 아니라 영원한 천국임을 알게된다

그러므로 이땅에 사는동안  고난이 있더라도 후에 있을 비교가 될수 없는 축복을 바라보며 기쁨으로 견디며 사는 자세를 주님이 원하시는 삶이라 더욱 믿어진다 

9.적용(나):
더 좋은 것을 예비하신 하나님을 믿고 따르며 늘 순종하는 삶을 살아내야겠다

10. 영적터치(단어/구절)
40절: 하나님이 우리를 위하여 더 좋은 것을 예비하셨은즉

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-04-26', '히브리서', '12장 1절 ~ 10절', '사랑하는 자에게 징계를, 받아 들이신 자에게 채찍질을', '[히12:1-10]
1 이러므로 우리에게 구름 같이 둘러싼 허다한 증인들이 있으니 모든 무거운 것과 얽매이기 쉬운 죄를 벗어 버리고 인내로써 우리 앞에 당한 경주를 하며
2 믿음의 주요 또 온전하게 하시는 이인 예수를 바라보자 그는 그 앞에 있는 기쁨을 위하여 십자가를 참으사 부끄러움을 개의치 아니하시더니 하나님 보좌 우편에 앉으셨느니라
3 너희가 피곤하여 낙심하지 않기 위하여 죄인들이 이같이 자기에게 거역한 일을 참으신 이를 생각하라
4 너희가 죄와 싸우되 아직 피흘리기까지는 대항하지 아니하고
5 또 아들들에게 권하는 것 같이 너희에게 권면하신 말씀도 잊었도다 일렀으되 내 아들아 주의 징계하심을 경히 여기지 말며 그에게 꾸지람을 받을 때에 낙심하지 말라
6 주께서 그 사랑하시는 자를 징계하시고 그가 받아들이시는 아들마다 채찍질하심이라 하였으니
7 너희가 참음은 징계를 받기 위함이라 하나님이 아들과 같이 너희를 대우하시나니 어찌 아버지가 징계하지 않는 아들이 있으리요
8 징계는 다 받는 것이거늘 너희에게 없으면 사생자요 친아들이 아니니라
9 또 우리 육신의 아버지가 우리를 징계하여도 공경하였거든 하물며 모든 영의 아버지께 더욱 복종하며 살려 하지 않겠느냐
10 그들은 잠시 자기의 뜻대로 우리를 징계하였거니와 오직 하나님은 우리의 유익을 위하여 그의 거룩하심에 참여하게 하시느니라

