4.주제만들기: 사랑하는 자에게 징계를, 받아 들이신 자에게 채찍질을
5.하나님 찾기 (관찰)
- 기쁨을 위하여 십자가를 참으심
- 부끄러움을 개의치 아니하시고 하나님 우편에 앉으심
- 자신을 거역한 자들을 참으심
- 사랑하시는 자를 징계하시고, 받아들이시는 자를 채찍질하심
- 하나님의 아들과 같이 대우하심
6.인간 찾기 (관찰)
-무거운 것과 얽매이기 쉬운 죄에서 벗어나 우리 앞에 당한 경주를 하여 예수님을 바라보길 권면함
- 죄를 위해 싸웠으나 피흘리기까지 대항하지 않았고 하나님께서 권면하신 말씀을 잊음
7.하나님 찾기 (해석) 
- 하나님께선 우리를 위해 십자가의 수치를 참으셨다. 십자가의 부끄러움을 개의치 아니하시고 하나님 보좌 우편에 앉아 계신 분이시다.
- 하나님께선 우리를 사랑하시기 때문에 징계를 주신다. 그리고 받아들이신 아들에게 채찍질을 하신다. 하나님의 사랑은 완전하지만 하나님의 사랑을 이용하는 인간의 행태를 그냥 보시진 않으신다. 우리를 사랑하시기 때문에 돌이킬 수 있도록 징계도 주시고 채찍질도 하시며 우리를 죄에서 보호하신다. 
- 인간의 죄가 얼마나 완악하기에 하나님의 징계와 채찍질이 필요할까. 채찍질과 징계로까지 나를 붙잡아주시는 하나님의 사랑에 감사하다.
8.인간(해석):
- 우리는 예수님을 바라보며 죄에서 벗어나야 한다. 죄와 싸운다고 하지만 피흘리까지 전투적으로 싸운 적은 없다. 우리의 죄는 그러하다. 전투적으로 싸워야할 정도로 죄를 끊어버리는 일이 쉬운 것이 아니다. 
9. 적용(나): 
- 하나님의 은혜로 피흘리며 전투하는 목사님과 전도사님을 만나게 해주셔서 감사하다. 전투를 하는 심정으로 죄에서 벗어나길 소망하며 이런 사역에 NKFC가 동참하길 소망한다. 
- 하나님께선 사랑하기 때문에 우리를 놔두고 지켜보시기만 하는 분이 아니다. 우리를 위해 징계와 체찍질을 사용하여 우리를 이끌어주신다. 하나님의 은혜에 감사하는 하루가 되어야겠다. 
- 내게 주신 소명을 완수하기에 갈길이 너무 멀다. 죄와의 싸움을 이겨내길 소망한다.
10. 영적터치(단어/구절)
- 6 주께서 그 사랑하시는 자를 징계하시고 그가 받아들이시는 아들마다 채찍질하심이라 하였으니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

