2024년 월 일 장 절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
사람: 14, 15
소리: 19(3)

4.주제 만들기: 하나님의 은혜 안에 거하라

5.하나님 찾기 (관찰)
- 하나님은 연단 받은 사람들에게 의와 평강의 열매를 맺게 하시려고 징계를 주심 
- 저는 다리로 하여금 어그러지지 않고 고침을 받게 하심

6.인간 찾기 (관찰)
- 모든 징계는 연단 받은 사람들에게 의와 평강의 열매를 맺게 함
- 피곤한 손과 연약한 무릎을 일으켜 세우고
- 너희 발을 위하여 곧은 길을 만들어야 함
- 거룩함 없이는 아무도 주를 보지 못함
- 그리스도인은 만질 수 있고 불이 붙는 산과 침침함과 흑암과 폭풍과 나팔 소리와 말하는 소리가 있는 곳에 이른 것이 아님
- 구약의 백성들은 짐승이라도 그 산에 들어가면 돌로 침을 당하리라 하신 명령을 그들이 견디지 못함

7.하나님 찾기 (해석) 
- 하나님이 그리스도인에게 훈련을 주시지만 그 훈련을 통해 연단 받은 사람들은 의와 평강의 열매를 맺게 된다.
- 이 원리를 알고 훈련에 똑바로 임하는 자의 저는 다리를 고쳐 주신다. 죄로 인해 문제가 되었던 것을, 영적으로 문제가 되었던 것을, 고통이 되었던 것을 낫게 하여 주신다.

8.인간(해석): 
- 훈련 받는 시간은 괴롭지만, 이 훈련으로 연단받은 사람들에게는 의와 평강의 열매를 주심을 믿고 힘을 내야 한다.
- 이것을 믿고 모든 훈련을 똑바로 받으면, 문제가 되었던 것이 그 이전보다 더 나아지게 된다.
- 거룩해지지 않고서는, 아무도 주님을 뵐 수 없다. 
- 그리스도인은 하나님의 은혜에서 떨어져 나가지 않도록 조심해야 한다. 
- 은혜에서 떨어져 나가면,
- 쓴 뿌리가 돋아나서 괴롭게 하고, 많은 사람이 더러워지기 때문이다.
- 거룩을 위해 음란하면 안 되며,
- 음식 한 그릇에 장자권을 팔아 넘긴 에서와 같은 사람이 되지 않도록 주의해야 한다.
  정욕을 위해 하나님의 은혜의 자리를 떠나서는 안 된다는 것이다.
- 에서는 장자권을 팔아 넘긴 후에 장자의 축복을 받고자 눈물로 구했으나 버린 바 됨.
- 그리스도인은 모세 시대의 시내산에 이른 것이 아님.
- 모세 시대 이스라엘 백성들은 짐승이라도 그 산에 들어가면 돌로 침을 당하리라 하신 명령을 견디지 못함. 여호와 하나님이 무서워 산에 올라가지 못했음.

9.적용(나):
- 거룩할 수 있는 것은 주 예수 그리스도의 보혈로 인함이고,
- 지속적으로 거룩을 유지할 수 있는 것은 거룩한 영이신 성령님과 늘 교제하는 것 뿐이다.
- 내 힘과 의지로 거룩할 수 없기에, 주 예수 그리스도를 바라보고 성령님과 늘 교제해야 한다.  

10. 영적터치(단어/구절)  
  15 하나님의 은혜에 이르지 못하는 자가 없도록 하고
  
