6.인간 찾기 (관찰)
하나님의 권의 앞에서 두렵고 떠는 모세
흔들리지 않는 나라를 받은 성도들
경건함과 두려움으로 하나님을 기쁘시게 섬길 성도들의 직분

7.하나님 찾기 (해석)
모든 만민의 심판자이신 살아계신 하나님 께서 마지막때 모든 죄악들을 섬멸하신다고 기자는 단언하고 있다

그것은 하나님은 29절에 "하나님은 소멸하는 불" 이라고 기록 처럼 하나님을 거역하는 것들을 태워버린다는 것이다  그때는 세상에서 인간들이 그토록 얻고자 했던 세상의 "부귀영화" 가 허상 으로 나타날것이다
특히 스스로 높아지려고 했던 큰 죄악들이 얼마나 허무하고 허상인지 심판 가운데 알게 될것이다

그러나 사랑의 하나님은 새 언약의 중보자이신 예수의 피  를 통하어 모든 인간들에게 지속적인 용서와 회개의 기회를 주시고 계신다

8.인간(해석):
죄 가운데서 빠져나오지 못하고 죽음의 심판을 받아 하나님의 분노의 심판을 받을 인간들이 다시 생명의 빛으로 나올수 있는 기회를 받았다

오직 보혈의 피를 의지함에 사망의 떨리고 두려움이 아닌 은혜를 받을 자비를  받았다. ''흔들리지 않는 주의 나라''를 받는 두려움 즉 하나님을 경외하고 공경하는 성도로 인도함을 받았다

9.적용(나):
하나님을 더욱 경외하는 사람이 되야겠다.

