7.하나님 찾기 (해석) 
- 인간을 사랑하셔서 인간을 창조하신 하나님. 
- 우리를 영원히 사랑하시고, 우리가 영원히 서로 사랑하기를 원하셔서 영원한 효력이 있는 제사로 십자가를 감당하신 예수님. 
- 하나님의 사랑과 은혜는 어제나 오늘이나 영원히 동일하심

8.인간(해석): 
- 영원히 동일하신 예수님의 은혜와 사랑을 기억하며 우리도 서로 사랑해야 함
- 손님(나그네) 대접을 잊어서는 안 된다. 부지중에 천사를 대접한 이가 있었다.
- 갇힌 자와 학대받는 자를 생각하라. 우리는 그리스도 안에서 한 지체이다. 그가 고통받는 것을 내가 고통받는 것으로 여길 수 있어야 한다.
- 결혼을 귀하게 여겨라. 결혼 후 잠자리는 더러운 것이 아니다.
- 결혼 후의 잠자리를 더럽히는 음란과 간음을 멀리해야 한다.
- 주님이 보호하시고 도우시니 주님을 바라고, 돈을 사랑하지 말라
- 말씀을 전한 지도자들의 삶을 본받으라
- 여러 가지 다른 교훈에 끌리지 말고, 은혜로써 마음을 굳게 하라.
- 구약의 제사장들은 그리스도의 은혜의 제단에서 먹을 권한이 없다.

