4.주제만들기: 거룩한 예배와 이웃 사랑 실천
5.하나님 찾기 (관찰)
- 우리를 거룩하게 하시려 성문 밖에서 고난을 당하심
- 찬송의 제사와 선을 행함과 서로 나누어 주는 것을 기뻐하심
6.인간 찾기 (관찰)
- 십자가 고난을 당한 예수님의 치욕을 따라 영문 밖으로 나아가야 함
- 찬송의 제사는 하나님을 증언하는 고백이며 선을 행함과 나누어주는 일을 잊어서는 안됨
- 영적 지도자에게 순종해야하고 지도자를 근심하도록 해서는 안됨
- 리더들을 위해 기도해야 함
7.하나님 찾기 (해석) 
- 과거 동물의 피는 성소에 들어갔지만 육체는 영문 밖에 버려지면서 거룩함과 죄를 완전히 불리시켰다. 예수님께서도 동일하게 성문 밖에서 고난을 받으심으로 우리의 죄를 분리시키셨다. 
- 하나님께서는 찬송의 제사도 좋아하시지만 이웃 사랑을 기뻐하신다고 말씀하셨다. 그만큼 인간은 이웃을 사랑하는 행동을 실천하지 못하는 나약한 존재이다. 진심으로 타인을 사랑하는 마음이 우리 안에 가득 임하길 소망한다.
8.인간(해석):
- 이 땅에 무너질 도성을 바라보는 것이 아니라 영원한 도성을 쫓아가는 삶을 살아야 한다. 
- 영적 리더에게 순장하고 복종함으로써 리더가 하나님으로부터 받은 말씀을 실천하는데 어려움이 없도록 도와야 한다.
9. 적용(나): 
- 하나님께 드리는 신령과 진정한 예배는 당연하고 이웃 사랑을 실천하는 것도 하나님께서 주신 명령이다. 이웃 사랑을 실천할 수 있는 마음과 용기가 내 안에 임하길 원한다.
- 영원할 것 같은 이 세상의 부귀영화보다 하나님의 말씀에 집중하고 순종하여 영원한 도성을 꿈꾸는 사람이 되길 소망한다. 
