8.인간(해석):
히브리서 기자는 서신서 마무리를 하며   모든 믿음의 동역자들이  주님안에서 은혜 받기를 바라며 문안인사로 마무리하고 있다

21절에 의하면 성도들은 선한일을 행하여 온전해 질것을 당부하고 있는데 ''선한일'' 이란 주님의 뜻을 행함을 의미한다

주님의 뜻을 알기 위해서는  먼저 주님의 은혜안에 거할것을 알려준다.

은혜를 받기 위한 방법으로는 21절 의 오직 예수 그리스도를 말미암는다고 되어있다 

성도 자신들의 의지와 꿈이 아닌 오직 주님의 꿈인 비전이다. 그것을 붙잡고  나아가는 성도는 주님안에서 더욱 온전하여지며 그들의 삶 가운데 늘 즐겁고 기쁜 마음을 영위해  나아가는 선한일 에 동참하는 주역이 될수있다. 

결국 그러한 선한 마음들이 모여있을때 다양한 성도들이 하나의 주님 중심의  은혜의 줄 로 묶여진 사랑의 공동체가  될수있다

그런까닭에 성도 각자가 매일 주님과 동행하며 말씀묵상(큐티) 하는것이 얼마나 소중하고 복된 일인가를 가늠케된다

9.적용(나):
주님의 뜻 대로 살기위해 더욱 노력해야겠다 

