7.하나님 찾기 (해석)
하나님은 자녀들에게 각종 연단을 주사 더욱 온전한 사람으로 살아가기를 원하신다. 특히 의심하지 않고 하나님을 의지하고 구하는 자에게는 지혜를 선물로 주신다.
높은자는 겸손함 을 겸비하고 낮은자는 담대함을 자랑하는 것을 하나님은 요청하신다

