4.주제만들기: 속지 말아야 할 사탄의 시험 
5.하나님 찾기 (관찰)
- 자기를 사랑하는 자들에게 약속하신 생명의 면류관을 준비하심
- 악에게 시험 받지 않으시며 아무도 시험치 않으심
- 좋은 은사와 온전한 선물을 주심
- 변함 없으시고 그림자도 없으심
- 진리의 말씀으로 우리를 낳음
6.인간 찾기 (관찰)
- 해가 뜨고 뜨거운 바람이 불어 풀을 말리면 꽃이 떨어지는 것처럼 세상의 부한 사람도 행하는 일이 쇠해짐
- 시험을 참는 자는 복이 있음
- 시험 받는 것을 하나님으로부터 받는다고 말해서는 안됨
- 시험 받는 것은 자신의 욕심으로 인함이며 욕심히 잉태하면 죄를 낳고 죄가 장성하면 사망을 낳음
- 듣기는 속히하고 말하기는 더디하여 성내는 것도 더디해야 함. 사람이 성내는 것은 하나님의 의를 이루지 못함
7.하나님 찾기 (해석) 
- 하나님은 우리를 시험치 않는 분이시다. 온전하고 거룩하신 하나님을 내가 처한 환경과 상황으로 원망해서는 안 된다. 
- 사탄의 시험을 하나님의 시험으로 착각해서는 안된다. 하나님께서는 좋은 은사와 온전한 선물을 우리에게 주셨다. 그것은 세상에서 사람들이 생각하는 측면이 아닐 수 있다. 그렇기 때문에 감사하는 마음으로 진리의 말씀을 붙잡아야 한다.
8.인간(해석):
- 세상 부귀영화도 끝이 있다. 끝이 보이는 일에 집중하는 사탄의 시험에 빠져선 안 된다. 자신을 사랑하는 자들에게 약속하신 하나님의 생명의 면류관을 붙잡아야 한다.
- 우리가 겪는 시험(고난)이 하나님께로부터가 아닌 나의 욕심과 죄로 인함임을 반드시 깨달아야 한다. 사탄은 하나님을 원망하게 하여 나의 죄를 바라보지 못하게 한다.  
- 우리 마음에 하나님을 사랑하는 마음이 가득해야 하는데 그것은 전적으로 하나님의 은혜이다. 하나님의 사랑을 깨닫고도 마음이 차갑게 식지 않도록 혹은 다시 뜨거워지도록 하나님의 은혜를 구해야한다. 
9. 적용(나): 
- 욕심을 내려놓고 죄에서 벗어나 온전하신 하나님을 붙잡고 살아가야겠다.
- 진리의 말씀, 생명의 면류관을 위해 하나님께서 내게 맡기신 소명을 성실히 실천해야겠다.
10. 영적터치(단어/구절)
- 13절: 사람이 시험을 받을 때에 내가 하나님께 시험을 받는다 하지 말지니 하나님은 악에게 시험을 받지도 아니하시고 친히 아무도 시험하지 아니하시느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

