8.인간(해석):
하나나님이 명령하신 가장 큰 법인 "네 이웃을 사랑하기를 네 몸과 같이 하라" 말씀 하심을 지킬때는 특별히 가나한자 힘없는 자 를 강조하신다.  세상에서 가난한 자 라고 취급 받더라도 그들이 하나님의 자녀라면 결코 영적으로 가난한자가 아님을 보여준다.

도리어 천국에서는 상속자로써  부한 사람들이다. 그러므로 하나님의 자녀들은 세상의 시각이 아닌 하나님의 관점에서 바로 볼수있어야 함에 일깨워주고 있다

가난한 자들이 설령 불신자라 하더라도 그들을 어떠한 단체안에서 결코 차별화 시켜서는 안된다. 그 이유는 그들또한 언젠가 주님  의 자녀로 거듭날 가능성이 있는 귀한 존재들 이기때문이다. 

9.적용(나):
모든 사람을 진심으로 섬기며 더욱 사랑해야겠다 

10. 영적터치(단어/구절)
1절: 사람을 차별하여 대하지 말라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-07', '야고보서', '2장 11절 ~ 20절', '말씀을 행함으로 믿음을 보이라', '야고보서 2장 11~20
11   간음하지 말라 하신 이가 또한 살인하지 말라 하셨은즉 네가 비록 간음하지 아니하여도 살인하면 율법을 범한 자가 되느니라
12   너희는 자유의 율법대로 심판 받을 자처럼 말도 하고 행하기도 하라
13   긍휼을 행하지 아니하는 자에게는 긍휼 없는 심판이 있으리라 긍휼은 심판을 이기고 자랑하느니라
행함이 없는 믿음은 죽은 것
14   내 형제들아 만일 사람이 믿음이 있노라 하고 행함이 없으면 무슨 유익이 있으리요 그 믿음이 능히 자기를 구원하겠느냐
15   만일 형제나 자매가 헐벗고 일용할 양식이 없는데
16   너희 중에 누구든지 그에게 이르되 평안히 가라, 덥게 하라, 배부르게 하라 하며 그 몸에 쓸 것을 주지 아니하면 무슨 유익이 있으리요
17   이와 같이 행함이 없는 믿음은 그 자체가 죽은 것이라
18   어떤 사람은 말하기를 너는 믿음이 있고 나는 행함이 있으니 행함이 없는 네 믿음을 내게 보이라 나는 행함으로 내 믿음을 네게 보이리라 하리라
19   네가 하나님은 한 분이신 줄을 믿느냐 잘하는도다 귀신들도 믿고 떠느니라
20   아아 허탄한 사람아 행함이 없는 믿음이 헛것인 줄을 알고자 하느냐

