4.주제만들기: 행함 없는 믿음은 죽은 것
5.하나님 찾기 (관찰)
- 아브라함이 하나님을 믿음으로 벗이라고 칭하여 주심
6.인간 찾기 (관찰)
- 아브라함을 이삭을 제단에 받침
- 아브라함은 행동으로 의로움을 보였고, 믿음이 온전하게 됨
- 야고보는 믿음으로만 의로움을 받는 것이 아니라 행함으로 의로움을 받을 수 있다 함
- 라합이 하나님의 사자를 접대하고 안내하여 행함으로 의로움을 받음
- 행함이 없는 믿음은 죽은 것임
7.하나님 찾기 (해석) 
- 믿음을 통해 행할 수 있는 용기를 주심. 
- 인간은 하나님을 믿고 행동을 따를 뿐인데 은혜와 축복을 부어주심
8.인간(해석):
- 야고보는 믿음과 행동이 함께 행해져야 함을 강조했다. 
- 단순하고 당연한 것처럼 보이지만 아브라함과 라합이 한 일은 사랑하는 아들을 바쳐야 했고, 목숨을 걸어야 하는 행동이었다. 우리가 믿음으로 행동할 땐 이러한 용기와 결단이 함께 따를 것이다. 
- 아브라함의 순종으로 예수님이 우리를 대신해 대속 죄물이 되어주셨다. 믿음으로 행동을 했을 때 하나님은 우리에게 감당할 수 없는 큰 은혜와 축복을 허락하신다.
9. 적용(나): 
- 믿음은 있지만 행하지 못하는 나의 영적 상태를 점검하고, 행동할 수 있는 용기와 결단이 내게 임하길 간절히 기도한다. 
- 오직 하나님 한분만 의지하며 그 분이 가신 길을 따라갈 때 하나님께서 나아가야할 길을 알려주실 것을 기도한다.
- 현재 내가 해야할 먼저 그의 나라와 그의 의를 구하는 것에 최선을 다해야겠다.
