8.인간(해석):
야고보는 두가지 지혜를 소개하고 있다
첫째는  하늘로부터 오는 지혜이다 이 지혜를 가진 사람은 늘 화평가운데 의의 열매를 맺을것이라 한다

반면에 두번째는  거짓된 지혜로써 출처는 ''악'' 이며 근본은 마귀라고 기록되어 있다  이러한 거짓지혜를 추종하는 사람의 마음에는 늘 시기와 질투가 가득하여 자신뿐만 아니라 주변을 늘 힘들게 하는 특징이 있다

그렇다고 한다면 하늘의 지혜와 땅의 자칭 거짓된 지혜가 만나면 어떠한 현상이 일어날까?

분명 충동과 갈등이 생길것이다. 이러한 분쟁이 시작된다면 마귀가 원하는 데로 갈것이다

그러나 다행히 하늘의 지혜는 이러한 문제까지 극복하고 해결할수있는 방법도 제시하고 있다
해결책으로는 17절 "긍휼"이라 보어주듯이 땅의 어두운 마음  즉 시기 질투 다툼 등 의 마음을 가진 사람들을 도리어 불쌍한 마음으로 대한다면  좋은 변화의 가능성이 생길것이라 여겨진다
이러한 기대를 갖고 행함의 믿음을 야고보는 강조한것으로 생각된다

9.적용(나):
하늘의 지혜를 더욱 구하여 선한 의의 열매를 맺고살도록 힘써야겠다 

