4.주제만들기: 두 마음을 품는 인간을 사랑하시는 예수님
5.하나님 찾기 (관찰)
- 시기하기까지 사모하심
- 교만한 자를 물리치시고 겸손한 자에게 은혜를 주심
- 하나님을 가까이하는 자에게 가까이 하심
- 주 앞에서 낮추면 주께서 우리를 높이심
6.인간 찾기 (관찰)
- 싸움과 다툼은 정욕으로부터 난다
- 욕심으로 살인하고 시기하여 다투고 싸워도 얻지 못함은 구하지 아니하여서가 아니라 구하여도 정욕으로 쓰려고 잘못 구하기 때문이다.
- 세상과 벗된 것은 하나님과 원수되는 것이다
- 하나님께서 복종하고 마귀를 대적하면 우리를 피한다.
- 하나님을 가까이고 손을 깨끗이 하여 두 마음을 품지 말고 마음을 성결하게 해야 한다. 
7.하나님 찾기 (해석) 
- 하나님은 우리가 구하는 것이 하나님의 선하심과 우리의 유익을 위해 사용될지를 알고 계신다. 그렇기 때문에 우리가 정욕으로 구하는 것들을 이루어 주실 수 없다. 
- 하나님은 우리에게 은혜를 주셨고 교만한 자도 물리쳐 주시며 모든 밥상을 차려주신다. 인간은 그저 겸손하게 따르기만 하면 은혜를 주신다. 그런데 우리는 겸손하지 못하다.
- 우리가 겸손한 마음을 품고 있다면 주님께선 우리를 높여주신다.
- 하나님은 우리를 시기하기까지 사모하신다. 하나님께선 우리를 위해 우리 내면에서 활발히 활동하시는데 우리는 그것을 깨닫지 못한다.
8.인간(해석):
- 인간의 다툼은 정욕으로부터 시작된다. 욕심을 내거나 시기하여 얻지 못하는 것은 구하지 않기 때문인데, 날마다 기도한다고 하여도 그 기도의 내용이 정욕으로 쓰여진다면 하나님께선 기도를 들어주실 수 없다. 우리는 우리가 구한 것으로 넘어질 수 있는 연약한 존재이다. 그렇기 때문에 하나님께선 우리를 훈련시켜 주신다. 누구는 비교적 빠른 시간에 훈련되어 유익을 쫓는 삶을 살지만 누구는 훈련의 시간이 오래 걸릴 수도 있다. 훈련임을 깨닫고 인내하여야 한다.
- 내가 구하는 것들 대부분은 나의 정욕을 위한 것들이다. 의로운 척하지만 내 안엔 나의 욕망과 더러움으로 가득차 있다. 
9. 적용(나): 
- 내 안에 정욕이 사라지고 하나님께서 원하는 삶을 따라가도록 하나님의 뜻을 구해야겠다. 
- 하나님께서 시기하기까지 우리를 사모하시는 것에 감사하고 그 분의 세밀한 음성에 귀기울여야겠다.
10. 영적터치(단어/구절)
- 5 너희는 하나님이 우리 속에 거하게 하신 성령이 시기하기까지 사모한다 하신 말씀을 헛된 줄로 생각하느냐
