5.하나님 찾기 (관찰)
- 가장 자비하시고 긍휼히 여기시는 이

6.인간 찾기 (관찰)
- 인내하는 자는 복되다
- 맹세하지 말라
- 고난 당하는 자는 기도하고 즐거워하는 자는 찬송하라
- 병든 자는 죄를 고백하고 병이 낫기를 위하여 기도하라
- 엘리야가 기도하매 삼년 육개월 동안 비가 오지 않음
- 죄인을 미혹된 길에서 돌아서게 하는 자는
- 그의 영혼을 사망에서 구원할 것이며 허다한 죄를 덮을 것이다

7.하나님 찾기 (해석) 
- 하나님의 무궁한 자비와 긍휼하심을 의지하면 죄인은 구원받고 병든 자는 나음을 입을 수 있다. 

8.인간(해석): 
- 우리에게 고난이 있으나 믿음으로 인내해야 한다
- 우리는 맹세를 지킬 수 있는 존재가 아니다. 일을 이루시는 분은 하나님이시니 우리는 그렇다 아니다 대답하면 충분하다.
- 고난 가운데 있는 사람은 주님의 자비와 긍휼을 구하며 기도해야 한다.
- 즐거워하는 사람은 즐거움을 허락하신 하나님을 찬송해야 한다.
- 모든 것은 주님 안에서 이루어진다. 
- 내가 능력이 좋거나 의로워서 즐거움이 온 것이 아님을 기억해야 한다. 
- 모든 것은 주님의 주권에 달려 있다.
- 병든 자는 교회 지도자를 불러 기도를 받고, 또한 자기 죄를 고백하고 낫기를 바라며 기도해야 한다.
- 엘리야의 기도로 비가 삼년 육개월 동안 오지 않은 것처럼 기도에는 놀라운 능력이 있다.
- 자비와 긍휼이 무궁하신 하나님의 능력이 나타나기 때문이다.
- 미혹되어 떠난 자를 돌아서게 해야 한다.
- 돌아서게 한 자는 그들 사망에서 구원하는 것이며 허다한 죄를 덮는 것이다.
- 이것은 사랑 없이는 할 수 없는 것인데, 주님의 사랑으로 계속 기도하면서 돌아오길 바래야 한다.
- 이 모든 것은 주님의 자비와 긍휼하심을 의지하고 기도할 때 이루어지는 것이다.
- 이루시는 분은 하나님이시다.

9.적용(나)
- 하나님의 자비와 긍휼을 의지하여 기도하고, 
- 고난 가운데 주님의 능력으로 인내하고 즐거울 때 주님 바라보며 찬송해야겠다. 
- 오늘도 주님이 기뻐하시는 일들을 해야겠다.

