4.주제만들기
5.하나님 찾기 (관찰)
- 긍휼이 많으심
- 예수그리스도를 죽은 자 가운데서 부활하심
- 우리를 거듭나게 하시고 산 소망을 주심
- 썩지 않고 더럽지 않고 쇠하지 않은 유업을 잇게 하심
6.인간 찾기 (관찰)
- 하나님 아버지의 미리 아심과 성령으로 거룩하게 함, 예수 그리스도의 피 뿌림을 통해 선택된 사람들로, 순종과 구원을 얻기 위해 부르심을 받음
- 하나님의 능력으로 보호하심을 받음
- 여러 시험으로 인해 잠깐 근심하지만 오히려 기뻐함. 믿음의 확실함은 불로 연단하여도 없어질 금보다 더 귀하여 예수 그리스도께서 나타나실 때에 칭찬과 영광과 존귀를 얻게 됨 
- 예수그리스도를 보지 않고도 사랑하였고 기뻐함
- 믿음은 영혼의 구원을 받음
7.하나님 찾기 (해석) 
- 하나님의 긍휼하심과 전적인 사랑으로 우리는 구원을 받았고, 세상에서의 소망이 아닌 하늘에 간직된 유업을 기대하는 소망을 갖게 됨.
8.인간(해석):
- 우리는 예수님의 사랑으로 부르심을 받은 택함 받은 자들이다. 
- 하나님의 능력이 우리를 보호하기 때문에 여러 시험이 있지만 오히려 기뻐할 수 있는 것은 이러한 과정이 믿음을 강하게 하여 하나님의 영광이 되기 때문이다. 
- 우리는 예수님을 직접 보지는 못하였지만 성령님을 통해 예수님을 만날 수 있다. 그분의 사랑을 느낄 수 있고, 우리도 예수님을 사랑할 수 있다.
- 믿음을 통해 우리는 영혼의 구원 얻는다. 하나님을 믿을 수 있는 믿음, 살아계신다는 확신, 예수 그리스도의 십자가의 사랑을 믿는 믿음은 우리의 영혼을 살린다. 
9. 적용(나): 
- 택함 받은 것에 감사하는 하루를 보내야겠다.
- 우리가 이 땅에서 받는 여러 시험을 감사해야겠다. 이를 통해 나의 믿음이 더욱 굳건해지고 하나님의 영광을 더욱 드러낼 수 있다.
- 믿음으로 영혼 구원을 얻은 것처럼 영혼 구원이 필요한 사람들을 위해 전도에 집중해야겠다.
10. 영적터치(단어/구절): 택함 받음 자들
