8.인간(해석):
지금은 흔히 말세의 시대에 산다고 한다 하지만 말세를 정확히 아는 사람은 없다 그저 예측할뿐이다.  20절에 보먼 "말세에 너희를 위하여 나타내신 바 되었으니" 기록되어 있다  그러므로 그리스도의 보배로운 피는 마지막까지 유효함을 알수있다 

우리를 지켜주신다는 하나님의 은혜라고 베드로는 확신하고 있다

다만 보배로운 피를 힘입어 헛된 행실에서 벗어나 거룩한 자로써 더욱 살아나야함을 분명히 보여주고 있다

베드로는 예수님과 더불어 지냈을때는 온전히 거룩한 행실을 이룬자는 아니었다. 심지어 배신까지 하였던 인물이었다

하지만 예수님의 부활하심과 십자가의 거룩한 피 의 의미를 깨우치야 참된 복음의 통로로 쓰임을 받을수 있었다

베드로는 20절의 기록처럼 "그는 창세 전부터 미리 알린 바되신" 알리는 자로 사용 받고있다. 누구든지 이 복음의 진리를 받아들이고 깨우친다면  알리는 자로 살아갈수 있음을 도전하고 있다

9.적용(나):
거룩한 보혈의 피를 믿음으로 더욱 거룩한 행실을 하는 사람이 되도록 노력해야겠다 

10. 영적터치(단어/구절)
13절: 은혜를 온전히 바랄지어다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-18', '베드로전서', '1장 21절 ~ 25절', '', '(베드로전서 1장)
21. 너희는 그를 죽은 자 가운데서 살리시고 영광을 주신 하나님을 그리스도로 말미암아 믿는 자니 너희 믿음과 소망이 하나님께 있게 하셨느니라
22. 너희가 진리를 순종함으로 너희 영혼을 깨끗하게 하여 거짓이 없이 형제를 사랑하기에 이르렀으니 마음으로 뜨겁게 서로 사랑하라
23. 너희가 거듭난 것은 썩어질 씨로 된 것이 아니요 썩지 아니할 씨로 된 것이니 살아 있고 항상 있는 하나님의 말씀으로 되었느니라
24. 그러므로 모든 육체는 풀과 같고 그 모든 영광은 풀의 꽃과 같으니 풀은 마르고 꽃은 떨어지되
25. 오직 주의 말씀은 세세토록 있도다 하였으니 너희에게 전한 복음이 곧 이 말씀이니라

