4.주제만들기: 
영원토록 변치않으신 하나님 말씀 

5.하나님 찾기 (관찰): 
예수를 죽은 자 가운테서 살리시고 영광을 주신 하나님
세세토록 계실 하나님 말씀 
믿음과 소망을 공급하시는 하나님

6.인간 찾기 (관찰)
형제를 뜨겁게 서로 사랑하기

7.하나님 찾기 (해석)
하나님의 말씀은 영혼을 깨끗하게 하신다. 투명하게 된 영혼으들은  주님의 영광을 자연스럽게 보게되며 믿음과 소망을 가지게 될것이라 말하고 있다 

8.인간(해석):
시간과 세월의 흐름속에 육체를 가지고 태어난 모든 사람들은 풀과 꽃처럼 시들고 사라질것이다. 

반면에 하나님의 말씀은 시간과 공간을 초월하신 전능성이 있어서 늘 하나님의 영광을 비췰것이다. 

그 영광의 빛을 바라보며 믿는 자들에게는 하나님께서 새 소망을 주시며 세세토록 함께 하심을 베드로는 확신하고 있다

 매일 진리이신 하나님의 말씀을 붙잡고 살아간다면 형제를 뜨겁게 살아갈 것이라 설명한다

뿐만아니라 훗날 형제가 될 영혼들에게 말씀을 전파하는것이야 말로 형제를 사랑하는 첫 걸음이라 여겨진다


9.적용(나):
영원토록  함께하실 하나님말씀을 더욱 소중히 여기며 아직 믿지않는 영혼들에게 더욱 알리는데 힘써야겠다 

10. 영적터치(단어/구절)
25절: 오직 주의 말씀은 세세토록 있도다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-19', '베드로전서', '2장 1절 ~ 10절', '우리는 아름다운 덕을 선포해야 할 거룩한 제사장', '[벧전2:1-10]
1 그러므로 모든 악독과 모든 기만과 외식과 시기와 모든 비방하는 말을 버리고
2 갓난 아기들 같이 순전하고 신령한 젖을 사모하라 이는 그로 말미암아 너희로 구원에 이르도록 자라게 하려 함이라
3 너희가 주의 인자하심을 맛보았으면 그리하라
4 사람에게는 버린 바가 되었으나 하나님께는 택하심을 입은 보배로운 산 돌이신 예수께 나아가
5 너희도 산 돌 같이 신령한 집으로 세워지고 예수 그리스도로 말미암아 하나님이 기쁘게 받으실 신령한 제사를 드릴 거룩한 제사장이 될지니라
6 성경에 기록되었으되 보라 내가 택한 보배로운 모퉁잇돌을 시온에 두노니 그를 믿는 자는 부끄러움을 당하지 아니하리라 하였으니
7 그러므로 믿는 너희에게는 보배이나 믿지 아니하는 자에게는 건축자들이 버린 그 돌이 모퉁이의 머릿돌이 되고
8 또한 부딪치는 돌과 걸려 넘어지게 하는 바위가 되었다 하였느니라 그들이 말씀을 순종하지 아니하므로 넘어지나니 이는 그들을 이렇게 정하신 것이라
9 그러나 너희는 택하신 족속이요 왕 같은 제사장들이요 거룩한 나라요 그의 소유가 된 백성이니 이는 너희를 어두운 데서 불러 내어 그의 기이한 빛에 들어가게 하신 이의 아름다운 덕을 선포하게 하려 하심이라
10 너희가 전에는 백성이 아니더니 이제는 하나님의 백성이요 전에는 긍휼을 얻지 못하였더니 이제는 긍휼을 얻은 자니라

