2024년 5월 20일 베드로전서 2장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
 산돌(3,4절), 모퉁이돌(6,7절), 넘어지다(7절), 제사장(5,9절), 백성(10절), 긍휼(10절)
4.주제만들기: 우리는 아름다운 덕을 선포해야 할 거룩한 제사장
5.하나님 찾기 (관찰)
- 보배로운 모퉁잇돌을 시온에 두노니 그를 믿는 자는 부끄러움을 당하지 아니하리라 하심
6.인간 찾기 (관찰)
- 모든 악독, 기만, 비방, 외식, 시기를 버려함
- 갓난 아이와 같이 순전하고 신령한 젖을 사모해야 함
- 하나님이 기쁘게 받으실 신령한 제사를 드릴 거룩한 제사장이 되어야 함
- 믿지 않는 자들에겐 말씀을 순종하지 않기 때문에 넘어짐
- 택하신 족속, 왕같은 제사장, 거룩한 나라, 그의 소유가 된 백성은 어두운 데서 불러내어 빛에 들어가 아름다운 덕을 선포하게 하려 하심
7.하나님 찾기 (해석) 
- 모퉁이돌이 되신 예수님으로 인해 우리는 산 돌 같이 신령한 집으로 세워질 수 있게 되었다.
8.인간(해석):
- 인간은 끊임없이 악함과 기만과 외식과 시기과 비방하는 악함을 범한다. 우리는 늘 하나님을 사모해야하는데 아이가 엄마의 젖만 찾는 것처럼 우리도 하나님의 말씀을 찾고 따라야 한다. 
- 모퉁이 돌이 누군가에겐 집을 짓는 터가 되지만 누군가에겐 그저 부딪치는 돌과 걸려 넘어지게하는 돌이 될 수 있다. 예수님을 아는 우리도 마찬가지이다. 예수님의 인자하심을 맛본 우리는 하나님의 말씀에 순종하여 악에 넘어져서는 안된다.
- 우리가 택함 받은 것, 거룩한 제상이 되어야 하는 것은 어둠에서 빛으로 인도하신 하나님의 은혜와 사랑을 선포하기 위함이다. 선포의 방식은 성도마다 다를 수 있다. 각자의 방식으로 하나님을 선포해야 한다. 
9. 적용(나): 
- 노방전도에 힘써야겠다.
- 말씀에 귀 기울이고 하나님의 뜻이 무엇인지 그 뜻에 따라 순종하는 삶을 살아야겠다.
10. 영적터치(단어/구절)
- 9절 아름다운 덕을 선포하게 하려 하심이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-20', '베드로전서', '2장 11절 ~ 20절', '하나님의 종으로 살기', '베드로전서 2장
11   사랑하는 자들아 거류민과 나그네 같은 너희를 권하노니 영혼을 거슬러 싸우는 육체의 정욕을 제어하라
12   너희가 이방인 중에서 행실을 선하게 가져 너희를 악행한다고 비방하는 자들로 하여금 너희 선한 일을 보고 오시는 날에 하나님께 영광을 돌리게 하려 함이라
13   인간의 모든 제도를 주를 위하여 순종하되 혹은 위에 있는 왕이나
14   혹은 그가 악행하는 자를 징벌하고 선행하는 자를 포상하기 위하여 보낸 총독에게 하라
15   곧 선행으로 어리석은 사람들의 무식한 말을 막으시는 것이라
16   너희는 자유가 있으나 그 자유로 악을 가리는 데 쓰지 말고 오직 하나님의 종과 같이 하라
17   뭇 사람을 공경하며 형제를 사랑하며 하나님을 두려워하며 왕을 존대하라
18   사환들아 범사에 두려워함으로 주인들에게 순종하되 선하고 관용하는 자들에게만 아니라 또한 까다로운 자들에게도 그리하라
19   부당하게 고난을 받아도 하나님을 생각함으로 슬픔을 참으면 이는 아름다우나
20   죄가 있어 매를 맞고 참으면 무슨 칭찬이 있으리요 그러나 선을 행함으로 고난을 받고 참으면 이는 하나님 앞에 아름다우니라

3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 5월 21일 베드로전서 2장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
사랑: 11, 17
하나님: 12, 16, 17, 19, 20
순종: 13, 18
왕: 13, 17
선행: 14, 15
자유: 16(2)
고난: 19, 20

4.주제 만들기: 하나님의 종으로 살기

5.하나님 찾기 (관찰)
- 선행으로 어리석은 사람들의 무식한 말을 막으시는 것

6.인간 찾기 (관찰)
- 육체의 정욕을 제어하라
- 인간의 모든 제도를 주를 위하여 순종하라
- 하나님의 종과 같이 하라
- 사환들아 범사에 두려워함으로 주인들에게 순종하라

7.하나님 찾기 (해석) 
- 선을 행함으로 어리석은 자들의 무지한 입을 막는 것이 하나님의 뜻이기 때문

8.인간(해석): 
- 믿음을 가진 자로서 육체의 정욕을 피해야 함.
- 정욕대로 행하지 않고 믿음 안에서 바르게 행하면, 
- 믿지 않는 자들이 그리스도인이라는 이유로 비방하다가도 
- 그리스도인의 바른 행위를 보고 하나님께서 찾아오시는 날에, 
- 하나님께 영광을 돌릴 것이다.
- 인간의 모든 제도는 인간이 살아가면서 국가와 사회를 안전하고 바르게 유지하기 위해 만들어진 것이기에, 이것에 순종하는 것이 주를 위하여 바람직하다.
- 그리스도인은 자유인이지만, 악을 행하는데 자유로우면 안 된다. 
- 오직 하나님의 종과 같이 선한 것 안에서 자유를 누려야 한다.
- 사환(하인)은 주인에게 순종해야 한다.
- 착하고 너그러운 주인도 있지만, 까다로운 주인도 있다. 어떤 주인이든지 순종해야 한다.
- 억울하게 고난을 당하더라도, 하나님을 생각하면서 괴로움을 참으면, 그것은 아름다운 일이다.
- 선을 행하다가 고난을 당하면서 참으면, 그것은 하나님께서 보시기에 아름다운 일이다.

9.적용(나)
- 변화 받은 그리스도인으로서 육체의 정욕을 버리고, 믿음 안에서 바른 행위를 하며 살아야겠다.
- 주님의 영광을 위하여 그렇게 살아야겠다.

10. 영적터치(단어/구절)  
  20 선을 행함으로 고난을 받고 참으면 이는 하나님 앞에 아름다우니라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-21', '베드로전서', '2장 21절 ~ 25절', '그리스도의 자취를 따라', '베드로전서 2장 
21 이를 위하여 너희가 부르심을 입었으니 그리스도도 너희를 위하여 고난을 받으사 너희에게 본을 끼쳐 그 자취를 따라 오게 하려 하셨느니라
22 저는 죄를 범치 아니하시고 그 입에 궤사도 없으시며
