5.하나님 찾기 (관찰)
- 너희가 부르심을 받았으니 이는 복을 이어받게 하려 하심이라

6.인간 찾기 (관찰)
- 아내들아 이와 같이 자기 남편에게 순종하라
- 남편들아 이와 같이 지식을 따라 너희 아내와 동거하고 그를 더 연약한 그릇이요 또 생명의 은혜를 함께 이어받을 자로 알아 귀히 여기라
- 동정하며 형제를 사랑하며 불쌍히 여기며 겸손하며 악을 악으로, 욕을 욕으로 갚지 말고 도리어 복을 빌라

7.하나님 찾기 (해석) 
- 하나님은 복을 이어받게 하시려고 우리를 부르심
- 우리는 이것을 깊이 생각하고 말씀에 순종해야 함

8.인간(해석): 
- 아내가 믿음 안에서 경건하고 순결하게 행하면,
- 남편이 아내의 모습을 보고 예수님을 생각하고 바라보고 믿게 할 수 있다
- 외모를 단장하기 보다는 온유하고 정숙한 마음으로 속사람을 단장하라
- 선을 행하며 아무리 두려운 일이 있어도 무서워하지 않아야 한다.
- 남편은 아내가 여성으로 자기보다 약한 그릇임을 이해하고 함께 살아야 한다.
- 육체 뿐 아니라 정서적, 감정적으로 더 약하고, 섬세하기 때문에 남편은 아내를 대할 때 조심해야 한다.
- 생명의 은혜를 함께 상속 받는 사람이니 그것을 기억하고 존중해야 한다.
- 믿음 안에서 서로 동정하고 서로 사랑하며 자비를 베풀며 겸손해야 한다.
- 악을 악으로, 욕을 욕으로 갚지 말고 도리어 복을 빌어야 한다. 
- 복을 이어받게 하시려고 하나님께서 우리를 부르셨다.

9.적용(나)
- 내게 무례하게 행하는 사람들, 내게 불편을 주는 사람들에게 화가 날 때가 있다.
- 복을 이어받게 하시려고 나를 부르신 하나님을 기억하며 도리어 복을 비는 삶을 살아야겠다.

10. 영적터치(단어/구절)  
  9 이는 복을 이어받게 하려 하심이라
  
