12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-23', '베드로전서', '3장 11절 ~ 22절', '악에서 떠나 선한 양심으로 화평을 구하는 삶', '[벧전3:11-22]
11 악에서 떠나 선을 행하고 화평을 구하며 그것을 따르라
12 주의 눈은 의인을 향하시고 그의 귀는 의인의 간구에 기울이시되 주의 얼굴은 악행하는 자들을 대하시느니라 하였느니라
13 또 너희가 열심으로 선을 행하면 누가 너희를 해하리요
14 그러나 의를 위하여 고난을 받으면 복 있는 자니 그들이 두려워하는 것을 두려워하지 말며 근심하지 말고
15 너희 마음에 그리스도를 주로 삼아 거룩하게 하고 너희 속에 있는 소망에 관한 이유를 묻는 자에게는 대답할 것을 항상 준비하되 온유와 두려움으로 하고
16 선한 양심을 가지라 이는 그리스도 안에 있는 너희의 선행을 욕하는 자들로 그 비방하는 일에 부끄러움을 당하게 하려 함이라
17 선을 행함으로 고난 받는 것이 하나님의 뜻일진대 악을 행함으로 고난 받는 것보다 나으니라
18 그리스도께서도 단번에 죄를 위하여 죽으사 의인으로서 불의한 자를 대신하셨으니 이는 우리를 하나님 앞으로 인도하려 하심이라 육체로는 죽임을 당하시고 영으로는 살리심을 받으셨으니
19 그가 또한 영으로 가서 옥에 있는 영들에게 선포하시니라
20 그들은 전에 노아의 날 방주를 준비할 동안 하나님이 오래 참고 기다리실 때에 복종하지 아니하던 자들이라 방주에서 물로 말미암아 구원을 얻은 자가 몇 명뿐이니 겨우 여덟 명이라
21 물은 예수 그리스도께서 부활하심으로 말미암아 이제 너희를 구원하는 표니 곧 세례라 이는 육체의 더러운 것을 제하여 버림이 아니요 하나님을 향한 선한 양심의 간구니라
22 그는 하늘에 오르사 하나님 우편에 계시니 천사들과 권세들과 능력들이 그에게 복종하느니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 5월 23일 베드로전서 3장 11절~22절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 선(11,13,16,17절), 고난(14,17절), 행하라(11,12,13절), 구원(20,21절)
4.주제만들기: 악에서 떠나 선한 양심으로 화평을 구하는 삶
5.하나님 찾기 (관찰)
- 주의 눈은 의인을 향하시고
- 주의 귀는 의인의 간구를 들으시고
- 주의 얼굴은 악행을 행하는 자들을 대하신다
- 선을 행함으로 고난을 받는 것은 하나님의 뜻이다
- 죄를 위하여 죽으시고 의인으로 불의한 자를 대신하심은 우리를 하나님 앞에 인도하기 위함이다
- 육체로는 죽임을 당하셨으나 영으로는 살리심을 받으셨다
- 영으로 옥에 있는 자들에게 선포하신다.
- 예수님의 부활은 우리의 구원의 표와 세례이다.
- 하늘에 오르사 하나님 우편에 계시며, 천사와 권세와 능력이 예수님께 복종한다.
6.인간 찾기 (관찰)
- 악에서 떠나 선을 행하고 화평을 구하여 그것을 따라야한다
- 의를 위하여 고난을 받으면 복 있는 자다
- 그것을 두려워 하지말고 근심하지 말고 마음에 그리스도를 주로 삼아 거룩하게 하고
- 속에 있는 소망에 관한 이유를 묻는 자에게 대답할 것을 항상 준비하되
- 온유와 두려움으로 하고 선한 양심을 가져야 한다. 
- 이는 그리스도 안에 있는 선행을 욕하는 자들로 비방하는 일에 부끄러움을 당하게 하려 함이다
- 선을 행하여 고난 받는 것이 악을 행하여 고난 받는 것보다 낫다
- 노아의 방주를 준비할 동안 하나님이 오래 참고 기다시리 때 복종한 자, 구원 받은 자는 겨우 8명 뿐이었다. 
7.하나님 찾기 (해석) 
- 주님은 우리의 모든 것을 살피시는 분이시다. 주님께선 우리가 해야 할 일과 행실에 대해 분명히 말씀해 주신다. 우리는 그것을 따르고 행하기만 하면 되는데 연약한 인간, 연약한 죄인으로 내 의지로 쉽게 이루어지지 않는 것이 아쉽다. 그러함에도 불구하고 하나님께서 우리르 살피시고 우리를 힘들게 하는 모든 상황과 관계 가운데 우리를 대신하여 대적하시는 분이기 때문에 그 분을 믿고 따라야 한다. 
8.인간(해석):
- 우리의 선한 행실은 복음의 대상자들과 복음을 대적하려는 각종 종교와 세력으로부터 우리를 보호할 수 있다. 우리의 행실이 선하지 않은데 복음을 어떻게 전할 수 있으며, 복음에 대해 부정적인 인식을 심어줄 수 밖에 없다. 그렇기 때문에 늘 내 자신을 부인하고 십자가를 짊어지는 삶을 살아야 한다 .
- 우리는 선한 행실로 인해 고난 받는 것을 두려워하면 안 된다. 고난은 하나님의 뜻인데 고난으로 인해 대적하는 자들이 넘어지고 변화될 수 있다. 
- 그리고 우리가 소망을 품는 것을 기회가 주어질 때 전해야 한다. 복음을 전하는 기회가 우리에게 사라질 수 있다. 기회가 있을 때 소망을 전해야 한다.
9. 적용(나): 
- 전도에 소망을 품고 더욱 힘써 전해야겠다.
- 하나님께서 조재필 목사님을 먼저 깨닫게 하시고 전하는 우리들에게 깨어질 수 있는 마음을 허락해주시니 감사하다. 노방 전도는 우리의 소망이다. 
- 이제 전도지를 나누어주는 일은 익숙하다. 조금씩 상대방이 전도지를 받았으면 하는 마음도 든다. 영혼을 귀하게 여기는 마음이 내 안에 가득하길 원한다.
10. 영적터치(단어/구절): 소망
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-24', '베드로전서', '4장 1절 ~ 10절', '', '(베드로전서 4장)
1.  그리스도께서 이미 육체의 고난을 받으셨으니 너희도 같은 마음으로 갑옷을 삼으라 이는 육체의 고난을 받은 자는 죄를 그쳤음이니
2. 그 후로는 다시 사람의 정욕을 따르지 않고 하나님의 뜻을 따라 육체의 남은 때를 살게 하려 함이라
3. 너희가 음란과 정욕과 술취함과 방탕과 향락과 무법한 우상 숭배를 하여 이방인의 뜻을 따라 행한 것은 지나간 때로 족하도다
4. 이러므로 너희가 그들과 함께 그런 극한 방탕에 달음질하지 아니하는 것을 그들이 이상히 여겨 비방하나
5. 그들이 산 자와 죽은 자를 심판하기로 예비하신 이에게 사실대로 고하리라
6. 이를 위하여 죽은 자들에게도 복음이 전파되었으니 이는 육체로는 사람으로 심판을 받으나 영으로는 하나님을 따라 살게 하려 함이라
7. 만물의 마지막이 가까이 왔으니 그러므로 너희는 정신을 차리고 근신하여 기도하라
8. 무엇보다도 뜨겁게 서로 사랑할지니 사랑은 허다한 죄를 덮느니라
9. 서로 대접하기를 원망 없이 하고
10. 각각 은사를 받은 대로 하나님의 여러 가지 은혜를 맡은 선한 청지기 같이 서로 봉사하라

