INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-25', '베드로전서', '4장 11절 ~ 19절', '', '(베드로전서 4장)
11. 만일 누가 말하려면 하나님의 말씀을 하는 것 같이 하고 누가 봉사하려면 하나님이 공급하시는 힘으로 하는 것 같이 하라 이는 범사에 예수 그리스도로 말미암아 하나님이 영광을 받으시게 하려 함이니 그에게 영광과 권능이 세세에 무궁하도록 있느니라 아멘
12.  사랑하는 자들아 너희를 연단하려고 오는 불 시험을 이상한 일 당하는 것 같이 이상히 여기지 말고
13. 오히려 너희가 그리스도의 고난에 참여하는 것으로 즐거워하라 이는 그의 영광을 나타내실 때에 너희로 즐거워하고 기뻐하게 하려 함이라
14. 너희가 그리스도의 이름으로 치욕을 당하면 복 있는 자로다 영광의 영 곧 하나님의 영이 너희 위에 계심이라
15. 너희 중에 누구든지 살인이나 도둑질이나 악행이나 남의 일을 간섭하는 자로 고난을 받지 말려니와
16. 만일 그리스도인으로 고난을 받으면 부끄러워하지 말고 도리어 그 이름으로 하나님께 영광을 돌리라
17. 하나님의 집에서 심판을 시작할 때가 되었나니 만일 우리에게 먼저 하면 하나님의 복음을 순종하지 아니하는 자들의 그 마지막은 어떠하며
18. 또 의인이 겨우 구원을 받으면 경건하지 아니한 자와 죄인은 어디에 서리요
19. 그러므로 하나님의 뜻대로 고난을 받는 자들은 또한 선을 행하는 가운데에 그 영혼을 미쁘신 창조주께 의탁할지어다

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 5월 26일 베드로전서 4장11절~19절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
고난: 13절 15절 16절 19절
즐거워함: 13절(2) 
불시험/연단: 12절 
영광: 13절 16절 

4.주제만들기: 
고난에 참여하는 것으로 즐거워하자

5.하나님 찾기 (관찰): 
심판자 이신 하나님
구원자 이신 하나님
창조자 이신 하나님

6.인간 찾기 (관찰)
그리스도의 고난에 참여하는 것으로 즐거워하라
고난을 견디면서 도리어 하나님께 영광을 돌리라

7.하나님 찾기 (해석)
심판자 이시고 인간을 창조하신 하나님께서 그의 자녀들에게 ''고난''을 허락하신다. 

그 고난을 통하여 영적 성장의 기회도 되고 또한 크신 하나님이 얼마나 미쁘신 창조자이신지 깨우치도록 도움을 주는 안내자 역활을 하도록 하나님은 사용하신다

8.인간(해석):
누구나 "고난''을 좋아하거나 기뻐할 사람은 없을것이다. 가령 재정의 어러움 가족의 건강 문제 그리고 각종 인간관계의 문제들로 느끼는 스트레스와 걱정되는 마음을 누가 즐거워할수 있을까?

그런데 베드로는 "너희가 그리스도와 고난에 참여하는 것으로 즐거워하라" 말하고 있다. 과연 어떠한 근거로 말하고 있는 것일까?

답은 간단한듯 하다. 베드로는 소망을 더이상 이땅에 두고 있지않고 오직 천국에 두고 있기 때문에 가능할것이다.

고난 중에 선을 행하고 고난중에 더욱 미쁘신 창조주께 의지할것을 권고하고 있다

16절에 베드로는 고난을 받으면 부끄러워하지 말고 도리어 하나님께 엉광을 돌리라고 말하고 있다 과거 베드로가 예수님이 힘없이 군인들에게 끌려가실때 얼마나 허탈해하며 부끄러워 하였는지 가늠할수있는 부분이다

그러나 부활과 천국소망을 깨우친후 베드로는 ''고난''을 도리어 감사하고 있는 담대한 모습을 보여줌으료써 우리에게 도전을 주고있다

9.적용(나):
천국소맘을 품고 오늘도 담대하게 복음을 전파해야겠다

10. 영적터치(단어/구절)
13절: 그리스도와 고난에 참여하는 것으로 즐거워하라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-26', '베드로전서', '5장 1절 ~ 14절', '나이가 들수록 더 노력해야 할 본이되는 삶', '[벧전5:1-14]
1 너희 중 장로들에게 권하노니 나는 함께 장로 된 자요 그리스도의 고난의 증인이요 나타날 영광에 참여할 자니라
2 너희 중에 있는 하나님의 양 무리를 치되 억지로 하지 말고 하나님의 뜻을 따라 자원함으로 하며 더러운 이득을 위하여 하지 말고 기꺼이 하며
3 맡은 자들에게 주장하는 자세를 하지 말고 양 무리의 본이 되라
4 그리하면 목자장이 나타나실 때에 시들지 아니하는 영광의 관을 얻으리라
5 젊은 자들아 이와 같이 장로들에게 순종하고 다 서로 겸손으로 허리를 동이라 하나님은 교만한 자를 대적하시되 겸손한 자들에게는 은혜를 주시느니라
6 그러므로 하나님의 능하신 손 아래에서 겸손하라 때가 되면 너희를 높이시리라
7 너희 염려를 다 주께 맡기라 이는 그가 너희를 돌보심이라
8 근신하라 깨어라 너희 대적 마귀가 우는 사자 같이 두루 다니며 삼킬 자를 찾나니
9 너희는 믿음을 굳건하게 하여 그를 대적하라 이는 세상에 있는 너희 형제들도 동일한 고난을 당하는 줄을 앎이라
10 모든 은혜의 하나님 곧 그리스도 안에서 너희를 부르사 자기의 영원한 영광에 들어가게 하신 이가 잠깐 고난을 당한 너희를 친히 온전하게 하시며 굳건하게 하시며 강하게 하시며 터를 견고하게 하시리라
11 권능이 세세무궁하도록 그에게 있을지어다 아멘
12 내가 신실한 형제로 아는 실루아노로 말미암아 너희에게 간단히 써서 권하고 이것이 하나님의 참된 은혜임을 증언하노니 너희는 이 은혜에 굳게 서라
13 택하심을 함께 받은 바벨론에 있는 교회가 너희에게 문안하고 내 아들 마가도 그리하느니라
14 너희는 사랑의 입맞춤으로 서로 문안하라 
그리스도 안에 있는 너희 모든 이에게 평강이 있을지어다

[샘플]
3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 5월 27일 베드로전서 5장 1절~14절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 장로(1,5절), 양(2,3,절), 겸손(5,6절), 대적(8,9절), 은혜(10,12절), 고난(1,10절), 영광(4,10절)
4.주제만들기: 나이가 들수록 더 노력해야 할 본이되는 삶
5.하나님 찾기 (관찰)
- 교만한자를 대적하심
- 겸손한 자들에게 은혜를 주심
- 염려를 맡기면 돌보심
- 고난 당한 우리를 온전하게 하시고, 굳건하게 하시며, 강하고 견고하게 하심
6.인간 찾기 (관찰)
- 장로들에게 하나님의 양 무리를 치되 억지로 하지 말고
- 하나님의 뜻을 따라 저원함으로 하며
- 더러운 이득을 위하여 하지 말고
- 양 무리의 본이 되어야 함
- 그리하면 목자장이 나타나실 때 영광의 관을 얻음
- 젊은자는 장로에게 순종하고 겸손으로 허리를 동이어야 함
- 하나님의 능하신 손 아래에서 겸손해야 함
- 염려를 주께 맡겨야 함
- 근신하고 깨어서 마귀가 우는 사자 같이 삼킬자를 찾을 때
- 믿음으로 굳건하여 대적하여야 함
7.하나님 찾기 (해석) 
- 하나님께선 교만한 자를 살펴보시고 계신다. 교만한 자는 결국 하나님으로부터 책망을 받을 것이고 겸손한 자를 잊지 않으시며 은혜를 주신다.
- 하나님께선 염려를 맡기는 자를 돌보신다. 우리의 모든 염려와 걱정은 하나님 앞에 내려 놓으면 되는데 그 쉬운 일도 하지 못한다. 고난 당하는 우리를 굳건하게 하시고 강하고 견고하게 하시는 분이기에 우리도 하나님을 굳건하게 잡아야 하며 강한 의지로 흔들리지 말고 주님을 의지해야 한다.
8.인간(해석):
- 베드로는 장로와 청년 사이에서 발생할 수 있는 문제를 알려주며 장로는 본이 되어야 하고 청년은 순종하며 겸손해야 한다고 말한다. 이는 장로가 가진 권위로 청년을 무시할 수 있고, 자신의 생각이 고집되어 청년들을 어렵게 할 수 있다. 반면 청년들은 장로에게 순종하여 겸손함을 몸에 새기는 훈련을 해야하는데 우리 몸의 균형을 유지하는데 허리가 중요하듯이 허리를 겸손으로 동여매여 중심에서 벗어나지 않을 수 있다.
9. 적용(나): 
- 청년의 때에 어르신들의 섬김을 귀찮아하고 당연시 여겼던 죄를 회개한다. 청년의 때에 순종하는 자세와 겸손을 알았다면 얼마나 좋았을까?
- 앞으로 나이가 들어갈텐데 청년들을 겸손함으로 섬길 수 있는 훈련과 준비가 되어야겠다. 
10. 영적터치(단어/구절): 순종과 겸손
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-05-27', '베드로후서', '1장 1절 ~ 10절', '세상 속에서 신성한 성품에 참여하라', '베드로후서 1장
1   예수 그리스도의 종이며 사도인 시몬 베드로는 우리 하나님과 구주 예수 그리스도의 의를 힘입어 동일하게 보배로운 믿음을 우리와 함께 받은 자들에게 편지하노니
2   하나님과 우리 주 예수를 앎으로 은혜와 평강이 너희에게 더욱 많을지어다
3   그의 신기한 능력으로 생명과 경건에 속한 모든 것을 우리에게 주셨으니 이는 자기의 영광과 덕으로써 우리를 부르신 이를 앎으로 말미암음이라
4   이로써 그 보배롭고 지극히 큰 약속을 우리에게 주사 이 약속으로 말미암아 너희가 정욕 때문에 세상에서 썩어질 것을 피하여 신성한 성품에 참여하는 자가 되게 하려 하셨느니라
5   그러므로 너희가 더욱 힘써 너희 믿음에 덕을, 덕에 지식을,
6   지식에 절제를, 절제에 인내를, 인내에 경건을,
7   경건에 형제 우애를, 형제 우애에 사랑을 더하라
8   이런 것이 너희에게 있어 흡족한즉 너희로 우리 주 예수 그리스도를 알기에 게으르지 않고 열매 없는 자가 되지 않게 하려니와
9   이런 것이 없는 자는 맹인이라 멀리 보지 못하고 그의 옛 죄가 깨끗하게 된 것을 잊었느니라
10   그러므로 형제들아 더욱 힘써 너희 부르심과 택하심을 굳게 하라 너희가 이것을 행한즉 언제든지 실족하지 아니하리라

