5.하나님 찾기 (관찰)
- 신기한 능력으로 생명과 경건에 속한 모든 것을 우리에게 주셨음
- 신성한 성품에 참여하는 자가 되게 하심

6.인간 찾기 (관찰)
- 보배로운 믿음을 받은 자들에게 편지하는 베드로
- 하나님과 예수님을 앎으로써 은혜와 평화가 더욱 풍성하여지기를 바란다고 말하는 베드로
- 더욱 힘써 너희 믿음에 덕을, 덕에 지식을,
- 지식에 절제를, 절제에 인내를, 인내에 경건을,
- 경건에 형제 우애를, 형제 우애에 사랑을 더하라고 함
- 더욱 힘써 너희 부르심과 택하심을 굳게 하라

7.하나님 찾기 (해석) 
- 예수님께서는 권능으로 우리에게 생명과 경건에 속한 모든 것을 주셨다.
- 이것은 신적 성품에 참여하는 자가 되게 하려는 것이다.
- 세상을 살 때 주님이 주신 신적 성품으로 살아가야 한다.

8.인간(해석)
- 예수님이 주신 믿음은 보배로운, 매우 귀한 믿음이다.
- 하나님과 예수님을 알아갈수록 은혜와 평강이 더욱 풍성해진다.
- 예수님께서 권능으로 우리에게 생명과 경건에 속한 모든 것을 주셨는데,
- 이것은 신적 성품에 참여하는 사람이 되게 하시려는 것이다.
- 그러므로 우리는 더욱 힘써 너희 믿음에 덕을, 덕에 지식을,
- 지식에 절제를, 절제에 인내를, 인내에 경건을,
- 경건에 형제 우애를, 형제 우애에 사랑을 더해야 한다.
- 이것이 예수님이 주신 신적 성품을 이루는 길이다.
- 이런 것들이 갖추어지면 예수님을 알게 되고, 열매를 맺게 될 것이다.
- 이런 것들을 갖추지 못한 사람은,
- 맹인이고 멀리 보지 못하는 사람이며 죄 사함 받은 것을 잊어버린 사람이다.
- 그러므로 우리는 더욱 힘써서 신적 성품을 실천해야 한다.

9.적용(나)
- 예수님께 받은 믿음을 귀하게 여기며, 하나님과 우리 주 예수님을 알아가는데 더욱 힘써야겠다.
- 주님의 권능으로 생명과 경건에 속한 모든 것을 내게 주셨으니,
- 신성한 성품에 참여하기 위해 더욱 힘써야겠다. 

10. 영적터치(단어/구절)  
  4하 신성한 성품에 참여하는 자가 되게 하려 하셨느니라
  
