4.주제 만들기: 거짓 선지자에 대한 경고

5.하나님 찾기 (관찰)
- 경건하지 않은 자들을 벌하시는 하나님
- 이 벌은 후세에 경건하지 아니할 자들에게 본을 보이신 것
- 하나님은 범죄한 천사들을 용서하지 않으셨으며
- 노아 시대 세계에 홍수를 내리셨고
- 무법한 자들의 음란한 행실로 말미암아 
- 소돔과 고모라 성을 멸하심으로 
- 고통 당하는 의로운 롯을 건지심
- 주께서는 경건한 사람은 시험에서 건지시고
- 불의한 자는 벌하시고 심판 날까지 가두어 두실 것임

6.인간 찾기 (관찰)
- 교회 가운데에도 거짓 교사들이 나타날 것이며
- 그들은 멸망한 이단을 가만히 끌어들일 것임
- 그들은 주를 부인하고 임박한 멸망을 스스로 취하는 자들임
- 많은 사람이 그들을 본받아서 방탕하게 될 것임
- 더러운 정욕 가운데서 행하며 
- 주관하는 이를 멸시하는 자들은 
- 당돌하고 자긍하며 떨지 않고 영광 있는 자들을 비방함

7.하나님 찾기 (해석) 
- 하나님께서는 경건한 자들을 아끼지 않으시고 멸하셨는데,
- 이것은 후세에 경건하지 않은 자들에게 본을 보이기 위함이다.
- 현재를 살아가는 우리도 경건을 잃지 않도록 주의해야 한다. 

8.인간(해석)
- 거짓 선지자와 거짓 교사들이 우리 가운데 있을 것이고
- 많은 사람이 그들을 본받고 방탕하게 될 것임
- 교회는 이들을 주의하고 주 안에서 경건하게 살아야 함
- 경건하지 않은 자들로 인해 진리의 길과 경건한 자들이 비방을 당할 것인데
- 주께서는 경건한 사람을 건져내시고
- 불의한 사람은 벌하실 것임
- 역사를 보면 하나님께서는 불의한 자들을 반드시 벌하셨으며
- 이것은 현재와 미래에 있을 불의한 자들에게 본을 보이는 것임
- 오늘을 살아가는 우리도 경건하게 살아야 하며
- 불의한 데 빠지지 않도록 주의해야 함 

9.적용(나)
- 거진 선지자를 주의하고, 주 안에서 경건하게 살아야겠다.
- 비방을 받는 일이 있다는 것을 기억하고 
- 비방받을 때 건지시는 주님을 의지해야겠다. 
- 늘 경건하게 살고,
- 불의한 데 빠지지 않도록 주의해야겠다.

