즉 개인이나 단체에서 큰 고난과 위기를 만나면 평강을 갖기는 쉽지 않을것이다

하지만 성경은 분명히 방법을 제시하고 있다. 모든 흑암을 이기고 새 하늘과 새 땅을 예비하신 주님만 바라고 또한 예수 그리스도의 은혜와 그를 아는 지식에 자라게 되면 가능할것이다!!
아멘!!

