- 단 한번의 제사로 모든 죄를 사하셨기 때문에,
- 우리가 죄를 지었을 때 예수님의 영원한 제사로 우리는 살 수 있다.

8.인간(해석)
- 예수님을 사랑하는 자는 예수님의 계명을 지킨다.
- 예수님을 사랑한다 말하고 그 계명을 지키지 않는 자는 거짓말하는 것이다.
- 즉, 에수님을 사랑하지 않는 것이다.
- 이런 자는 진리(예수님)가 그 속에 없다. 
- 성경 지식은 있을 수 있으나 예수님은 없는 것이다.
- 예수님의 말씀을 지키는 자는, 즉 예수님을 사랑하는 자는 
- 하나님의 사랑이 참으로 그 속에서 온전하게 된 것.
- 예수님을 사랑한다 하면서 그 형제를 미워하는 자는 사실 어둠에 있는 것.
- 예수님의 새 계명 서로 사랑하라를 지키지 않는 것이기 때문
- 그의 형제를 사랑하는 자는 
- 서로 사랑하라는 새 계명을 지키는 것이기 때문에 빛(예수님) 가운데 거하는 것이다.

9.적용(나)
예수님의 몸된 교회를 사랑하고 지체들을 사랑하며 사는 것이 예수님의 뜻인데,
각 사람의 인격과 받은 은사와 가치관과 세계관이 달라서 화평하게 지내는 것이 여간 어려운 일이 아님을 느낀다.
그러나 모든 어려움 속에서 형제를 미워하지 않고 사랑하는 것이 주님의 뜻임을 알기에, 그저 묵묵히 기도하며 내가 할 일을 할 뿐이다.

주님께서 내게 이웃을 사랑하는 마음을 부어 주시길 기도할 뿐이다.

