그 진리(영원한 생명) 가운데 사는 사람은 늘 담대함을 주시는 주님 안에 사는 자녀들이다 

그러기 위해서는 순간순간 주님안에 거하고 있는지 정검하는 행위가 얼마나 중요한지 알수있다 주님안에 확고하게 거하기위해서는 기본적으로 경건하며 23절의 말씀대로 "아들을 시인하는 자에게는 아버지도 있느니라" 늘 주님과 교제하며 따라가는 삶을 살아야함을 사도요한은 일깨워주고 있다

9.적용(나):
늘 주님과 동행하는 삶을 살아야겠다. 그러기위해 기도와 3331큐티를 즐겨야겠다.

