INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-07', '요한일서', '3장 1절 ~ 10절', '하나님의 사랑을 깨닫고 그 사랑을 실천해야 하는 우리가 가져야할 태도', '[요일3:1-10]
1 보라 아버지께서 어떠한 사랑을 우리에게 베푸사 하나님의 자녀라 일컬음을 받게 하셨는가, 우리가 그러하도다 그러므로 세상이 우리를 알지 못함은 그를 알지 못함이라
2 사랑하는 자들아 우리가 지금은 하나님의 자녀라 장래에 어떻게 될지는 아직 나타나지 아니하였으나 그가 나타나시면 우리가 그와 같을 줄을 아는 것은 그의 참모습 그대로 볼 것이기 때문이니
3 주를 향하여 이 소망을 가진 자마다 그의 깨끗하심과 같이 자기를 깨끗하게 하느니라
4 죄를 짓는 자마다 불법을 행하나니 죄는 불법이라
5 그가 우리 죄를 없애려고 나타나신 것을 너희가 아나니 그에게는 죄가 없느니라
6 그 안에 거하는 자마다 범죄하지 아니하나니 범죄하는 자마다 그를 보지도 못하였고 그를 알지도 못하였느니라
7 자녀들아 아무도 너희를 미혹하지 못하게 하라 의를 행하는 자는 그의 의로우심과 같이 의롭고
8 죄를 짓는 자는 마귀에게 속하나니 마귀는 처음부터 범죄함이라 하나님의 아들이 나타나신 것은 마귀의 일을 멸하려 하심이라
9 하나님께로부터 난 자마다 죄를 짓지 아니하나니 이는 하나님의 씨가 그의 속에 거함이요 그도 범죄하지 못하는 것은 하나님께로부터 났음이라
10 이러므로 하나님의 자녀들과 마귀의 자녀들이 드러나나니 무릇 의를 행하지 아니하는 자나 또는 그 형제를 사랑하지 아니하는 자는 하나님께 속하지 아니하니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 6월 7일 요한일서 3장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 깨끗하게(3절), 죄(4,5,8,9절), 범죄(6,8,9절), 마귀(8,10절), 속하다(8,10절)
4.주제만들기: 하나님의 사랑을 깨닫고 그 사랑을 실천해야 하는 우리가 가져야할 태도
5.하나님 찾기 (관찰)
- 우리에게 사랑을 베푸심
- 우리의 죄를 없애려고 나타나심
- 하나님은 의로우심
- 하나님의 아들이 나타나신 것은 마귀의 일을 멸하려 하심
6.인간 찾기 (관찰)
- 요한은 하나님께서 우리에게 어떠한 사랑을 베푸셔서 하나님의 자녀라 일컬음을 받게 되었는지를 말하며 세상이 우리를 알지 못하는 것은 하나님을 알지 못하는 것과 같다고 했다.
- 우리가 지금은 장래의 모습을 알지 못하지만 하나님께서 나타나실 때 그와 같을 줄을 알며 그의 참모습을 그대로 볼 것이다.
- 주를 향하여 이 소망을 가진 자마다 그의 깨끗하심을 따라 자기를 깨끗하게 한다.
- 죄를 짓는 자마다 불법을 행하며 죄는 불법이다.
- 하나님께서 우리 죄를 없애려고 나타나신 것을 알며 그는 죄가 없으시다.
- 하나님을 안에 거하는 자는 범죄하지 아니하고 범죄하는 자는 하나님을 보지도 못하고 알지도 못하였기 때문이다.
- 죄를 짓는 자는 마귀에게 속한다. 마귀는 처음부터 범죄한다.
- 하나님께로부터 난 자는 죄를 짓지 않는데 하나님의 씨가 그의 속에 거하기 때문이고 범죄하지 못하는 것은 하나님께로부터 낫기 때문이다.
- 마귀의 자녀들은 드러나게 되며 의를 행하지 않고 형제를 사랑하지 아니하는 자는 하나님께 속하지 않는 것이다.
7.하나님 찾기 (해석) 
- 하나님의 사랑으로 우리의 죄를 사하기 위해 이 땅에 오셨다. 하나님은 의로우시고 죄 없으신 분인데 우리를 위해 인간의 몸으로 이 땅에 오셨고 마귀의 일을 멸하셨다.
8.인간(해석):
- 세상은 여전히 하나님의 존재를 부정한다. 그렇기 때문에 사역자나 선교사 등이 전하는 메시지를 온전히 받아들이지 못한다. 
- 우리는 하나님의 자녀로 하나님의 선한 사역을 위해 끝까지 영적 전쟁에서 승리해야 한다. 세상 사람들이 무시하더라도 하나님께서 주신 사명을 감당해야 한다. 
- 세상에 속해 있는 것은 죄에 빠지기 쉽다. 하나님 안에 거하고 의지적으로 자신을 깨끗하게 하는 자는 각종 시험을 이길 수 있다. 하지만 죄 많은 인간은 죄에 쉽게 빠질 수 있고 범죄할 수 있는 존재임을 잊지 말아야 한다. 
9. 적용(나): 
- 하나님께서 우리를 사랑하셔서 우리의 죄를 사해주심에 감사하다. 주님께서 맡기신 소명을 잘 감당하도록 노방전도와 NKFC 사역에 힘써야겠다.
- 죄는 단순히 죄에서 멈추지 않고 범죄에 빠지게 한다. 죄에 넘어가지 않도록 기도하며 범죄하지 않도록 붙잡아주신 하나님께 감사하다. 혹여나 내가 깨닫지 못하고 행하는 행위가 범죄하였다면 그것을 알게 하시길 원한다.
10. 영적터치(단어/구절)
- 1 보라 아버지께서 어떠한 사랑을 우리에게 베푸사 하나님의 자녀라 일컬음을 받게 하셨는가, 우리가 그러하도다 그러므로 세상이 우리를 알지 못함은 그를 알지 못함이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-08', '요한일서', '3장 11절 ~ 24절', '', '(요한일서 3장 11절~24절)
11. 우리는 서로 사랑할지니 이는 너희가 처음부터 들은 소식이라
12. 가인 같이 하지 말라 그는 악한 자에게 속하여 그 아우를 죽였으니 어떤 이유로 죽였느냐 자기의 행위는 악하고 그의 아우의 행위는 의로움이라
13.  형제들아 세상이 너희를 미워하여도 이상히 여기지 말라
14. 우리는 형제를 사랑함으로 사망에서 옮겨 생명으로 들어간 줄을 알거니와 사랑하지 아니하는 자는 사망에 머물러 있느니라
15. 그 형제를 미워하는 자마다 살인하는 자니 살인하는 자마다 영생이 그 속에 거하지 아니하는 것을 너희가 아는 바라
16. 그가 우리를 위하여 목숨을 버리셨으니 우리가 이로써 사랑을 알고 우리도 형제들을 위하여 목숨을 버리는 것이 마땅하니라
17. 누가 이 세상의 재물을 가지고 형제의 궁핍함을 보고도 도와 줄 마음을 닫으면 하나님의 사랑이 어찌 그 속에 거하겠느냐
18. 자녀들아 우리가 말과 혀로만 사랑하지 말고 행함과 진실함으로 하자
19. 이로써 우리가 진리에 속한 줄을 알고 또 우리 마음을 주 앞에서 굳세게 하리니
20. 이는 우리 마음이 혹 우리를 책망할 일이 있어도 하나님은 우리 마음보다 크시고 모든 것을 아시기 때문이라
21. 사랑하는 자들아 만일 우리 마음이 우리를 책망할 것이 없으면 하나님 앞에서 담대함을 얻고
22. 무엇이든지 구하는 바를 그에게서 받나니 이는 우리가 그의 계명을 지키고 그 앞에서 기뻐하시는 것을 행함이라
23. 그의 계명은 이것이니 곧 그 아들 예수 그리스도의 이름을 믿고 그가 우리에게 주신 계명대로 서로 사랑할 것이니라
24. 그의 계명을 지키는 자는 주 안에 거하고 주는 그의 안에 거하시나니 우리에게 주신 성령으로 말미암아 그가 우리 안에 거하시는 줄을 우리가 아느니라

