행함과 진실함으로 형제를 대하기
형제를 자신 목숨을 버릴정도로 사랑하기
형제를 미워하지 말기
주님 안에 거하기

7.하나님 찾기 (해석)

8.인간(해석):
형제를 미워하지 않고 그 형제들을 사랑하는 자 들에게 하나님은 그들에게 담대함 을 얻을수 있는 특권을 주신다

그 은혜 "담대함 을 얻음" 를 받은 자들이 구할때 하나님은 무엇이든지 응답하신다고 사도요한은 말하고 있다

그 만큼 하나님은 형제끼리 ''사랑''하는 모습을 너무나 기뻐하심을 알수있다

특별히 말로만 사랑하는것이 아니라 행함이 동반되야 진실된 사랑이라 말할수 있을것이다

예수님이 우리죄를 위하여 죽으셨던 희생된 사랑처럼 그런 고귀한 사랑을 따라함이 참 그리스도인 이라 요한은 강조한다

9.적용(나):
행함과 진실함으로 형제들을 더욱 사랑해야겠다 

