1:감동받는 단어나 구절 찾기(영적터치)

2024년 6월 10일 요한일서 4장 11절~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 사랑하는 자(1절) 사랑(2,16,17,18,19절), 거하다(12,13,15,16,절), 안에(12,13,15,16절), 두려움(18절)
4.주제만들기: 완전한 하나님의 사랑
5.하나님 찾기 (관찰)
- 아들을 세상에 구주로 보내심
- 성령을 우리에게 주심
- 하나님의 아들이라 시인하는 자들에게 함께 거하심
- 하나님은 우리를 사랑하심
6.인간 찾기 (관찰)
- 하나님이 우리를 사랑하신 것 같이 서로 사랑해야 함
- 서로 사랑하면 하나님이 우리 안에 거하시고 그의 사랑이 우리 안에 온전히 이루어짐
- 성령을 주사 우리 안에 거하심
- 하나님의 아들을 세상의 구주로 보내신 것을 보았고 그것을 증언함
- 누구든지 예수를 주라 시인하면 하나님이 그의 안에 거하고 그도 하나님 안에 거하게 됨
- 하나님은 사랑이시고 사랑 안에 거하는 자는 하나님 안에 거하고 그도 하나님 안에 거하게 됨
- 사랑이 우리를 온전히 이루게해 심판 날에 담대함을 가지게 할 것이고 주께서 이루신 것처럼 우리도 세상에서 그러하게 됨
- 온전한 사랑은 두려움을 내쫓고 두려워하는 자는 사랑 안에서 온전히 못 이룸
- 우리가 사랑할 수 있는 것은 하나님께서 우리를 먼저 사랑하셨기 때문
- 누구든지 사랑한다고 하며 형제를 미워하면 거짓말하는 것이고 하나님을 사랑하는 것이 아님
- 하나님을 사랑하는자는 그 형제를 사랑한다.
7.하나님 찾기 (해석) 
- 하나님의 사랑은 일반적이지 않다.
- 하나님의 아들이 예수님을 세상에 보내 모진 고난을 받게 하셨는데 그것은 우리의 죄와 우리로 하여금 완전한 사랑을 얻도록 하기 위함이다. 
- 하나님은 우리에게 하나님을 시인하는 자의 안에 거하신다고 하셨는데, 성령님을 통해 우리 안에 거하게 하시며 하나님을 통해 하나님 안에 거할 수 있는 안전장치를 만드셨다.
8.인간(해석):
- 인간이 얼마나 사랑하지 못하는 이기적인 존재인지 말해준다. 우리는 하나님을 시인하기만 하면 되는데 하나님을 시인하지 못해 하나님께서 주신 사랑을 누리지 못한다. 대다수의 사람들이 그럴 것 이다.
- 신앙 생활을 하는 크리스천도 마찬가지이다. 하나님을 알지만 그 안에 사랑 없이 지식적으로만 하나님을 아는 경우가 많다. 우리 안에 사랑이 있어야 하나님이 계시며 그 사랑을 나누어주어야 한다. 사랑에는 거짓이 없어야 하는데 매우 어려운 부분이다.
- 그럼에도 소망을 가질 수 있는 것은 하나님께서 우리를 사랑하시기 때문이다. 그분의 사랑을 깨닫는 순간 다른 사람을 사랑할 수 있는 용기가 생긴다.
9. 적용(나): 
- 스쳐지나가는 사람마져도 사랑할 수 있는 마음을 갖길 소망한다.
- 성령님이 내 안에 거하시며 나를 보호하시고 하나님께서 나를 이끄심으로 완전케 됨을 믿는다. 믿음으로 신앙의 성숙을 이루길 희망한다. 
- 노방전도와 사역에 힘써야겠다.
10. 영적터치(단어/구절)
- 20절 누구든지 하나님을 사랑하노라 하고 그 형제를 미워하면 이는 거짓말하는 자니 보는 바 그 형제를 사랑하지 아니하는 자는 보지 못하는 바 하나님을 사랑할 수 없느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

