증거: 9(2), 10(2)

4.주제 만들기: 세상을 이기는 믿음

5.하나님 찾기 (관찰)
- 물과 피로 임하신 예수님
- 이것을 증언하시는 성령님
- 성령님은 진리이시다
- 하나님이 아들에 대하여 증언하심

6.인간 찾기 (관찰)
- 예수께서 그리스도이심을 믿는 자마다 하나님께로부터 난 자
- 하나님을 사랑하는 자마다 예수님을 사랑한다
- 하나님의 계명들을 지키는 것이 하나님을 사랑하는 것이다
- 세상을 이기는 승리는 우리의 믿음이다
- 이 믿음은 예수님이 하나님의 아들이심을 믿는 것이다
- 하나님의 아들을 믿는 자는 자기 안에 증거가 있고, 하나님을 믿지 아니하는 자는 하나님을 거짓말하는 자로 만드는 것이다.
- 그 이유는 하나님께서 그 아들에 대하여 증언하신 증거를 믿지 않기 때문이다.

7.하나님 찾기 (해석) 
- 예수님은 물로 세례를 받으셨고, 
- 세례를 받을 때 성령이 비둘기처럼 임하셨으며,
- 하나님께서 이는 내 사랑하는 아들이라 친히 말씀하셨다
- 이것이 예수님이 하나님의 아들되심에 대한 하나님의 증언이다
- 이것을 증언하시는 이는 성령님이신데, 
- 예수님께서 세례 받으실 때와 사역하실 때 충만히 임하신 것과
- 더불어 예수님 승천 후 오순절에 강림하신 사건으로 증명된다.

8.인간(해석)
- 예수님을 그리스도로 믿는 자는 하나님으로부터 나왔기에
- 하나님을 사랑하는 자는 예수님을 사랑할 수 밖에 없다
- 하나님의 계명을 지키는 자는 예수님을 사랑하는 것이며
- 이 계명은 무거운 것이 아니다
- 왜냐하면 하나님에게서 난 사람은 세상을 이기기 때문이다.
- 세상을 이긴 승리의 이유는 우리의 믿음인데,
- 이 믿음은 예수님이 하나님의 아들이심을 믿는 믿음을 말한다
- 하나님이 예수님을 자기 아들이라고 증언하셨기 때문에
- 예수님을 믿는 사람은 이 증언이 참 임을 믿고 간직하고 있는 것이다
- 반대로 예수님을 믿지 않는 사람은 하나님의 증언을 믿지 않기 때문에 하나님을 거짓말하는 자로 만드는 것이다.

9.적용(나)
주 예수 그리스도께서 하나님의 아들이심을 믿는다.
그렇게 증언하신 하나님의 말씀을 믿으며, 이것을 증언하는 성령님과 물과 피의 사건도 믿는다.
믿음으로 주어진 승리는 누리며, 주어진 일들을 묵묵히 수행하는 자가 돼야겠다.

10. 영적터치(단어/구절)  
  10   하나님의 아들을 믿는 자는 자기 안에 증거가 있고
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

