그 영생을 주시고 인도하시는 하나님을 이미 경험한 요한은 15절" 우리가 무엇이든지구하는 바를 들으시는 줄을안즉" 을 통하여 자신이 처한 열악한 환경에서 벗어나기보다  세상에서 살고 있는 모든 영혼들이 구원받고 영생을 갖기만을 위하여 외치고 있다

9.적용(나):
영생을 주신 하나님께 감사하며 그 영생 있음을 더욱 나누는 자가 되야겠다

