6.인간 찾기(관찰)
- 사도 요한이 부녀와 자녀들에게 편지를 씀
- 계명대로 진리 안에서 살아가는 이들을 보고 매우 기뻤음
- 서로 사랑할 것을 권면
- 사랑하는 것은 계명을 따라 사는 것
- 계명은 다른 것이 아니라 사랑 안에서 살아야 한다는 것
- 속이는 자가 많이 나타남
- 그들은 예수님의 성육신을 고백하지 않음
- 이들은 속이자이며, 적그리스도임
- 예수님의 성육신을 인정하지 않고 다른 말을 하는 자는
- 집에 받아들이지도 말고, 인사도 하지 말라
- 그에게 인사하는 사람은 그의 악한 일에 동참하는 것
7. 하나님 찾기(해석)
8. 인간 찾기 (해석)
- 하나님께 받은 계명대로 진리 안에서 살아가야 함
- 말씀대로 살되, 서로 사랑해야 함
- 서로 사랑하라는 계명은 새로운 말이 아니라, 처음부터 있던 계명임
- 사랑 안에서 사는 것이 하나님의 계명대로 사는 것이니
- 우리는 사랑 안에서 살아야 함
- 예수님의 성육신을 부인하는 자가 많이 나타남
- 이 자들을 주의하고 따라서는 안 됨
- 이 자들이 와서 가르치려하면 
- 집에 받아들이지도 말고, 인사도 하지 말아야 함
9. 적용(나)
- 길이요, 진리요, 생명이신 예수님 안에서 살아가야 한다.
- 진리이신 예수님처럼 나도 서로 사랑하며 살아야 한다.
- 예수님은 가룟 유다도 사랑하셨다. 
10. 영적 터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

