5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 요한은 가이오를 향해 축복함
- 형제들이 가이오게 있는 진리를 증언했고, 요한이 심히 기뻐함
- 어떠한 것이든 형제, 나그네 된 자들에게 행하는 것은 신실한 일이다
- 그들이 교회 앞에서 받은 사랑은 증언하며 그들을 하나님께로 전송하길 원한다
- 그들이 주의 이름을 위해 나가며 이방인에게 아무것도 받지 아니하게 된다.
- 이와 같이 영접하는 것이 마땅하고 진리로 함께 일하는 자가 되게 해야 한다.
- 요한은 두어명을 교회에 임명했으나 으뜸되기를 좋아하는 자는 요한과 일행을 맞아들이지 않았고 악한 말로 비방하며 형제들까지 맞아들이지 않은 자가 있다.
- 이와 같은 자들을 본 받지 말고 선한 것을 본 받고 선으로 행하는 자는 하나님께 속한다.
- 악을 행하는 자는 하나님을 보지 못할 것이다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 요한은 가이오에게 편지를 하며 그가 하나님의 일을 성실히 행하고 진리를 잃지 않은 것에 크게 기뻐하며 축복했다. 당시 복음을 접한 이들을 관리하는 것이 쉽지는 않았을 것 같다. 거두어야 할 곡식은 많은데 일꾼이 부족하여 제대로 된 훈련을 받지 못하고 유혹에 넘어가 진리를 떠나는 사람들도 많았을 것 같다. 
- 또한 형제, 나그네에게 신실하게 하길 권면했는데 그들이 밖에서 그들의 사랑을 전하며 결국 주의 일을 하게 되기 때문이었다. 선을 결국 선으로 전파되어 선한 영향력을 이어지게 되어 있다. 선한 일에 열매 맺는 것을 단기간으로 바라볼 것이 아니라 장기적인 관점에서 바라보아야 한다.
9. 적용(나): 
- 하나님의 일을 할 때 서로를 진심으로 축복할 수 있는 리더가 되어야겠다. 
- 한 영혼, 한 영혼을 소중히 여겨 하나님을 전하는 일에 집중해야겠다. 
10. 영적터치(단어/구절)
-5 사랑하는 자여 네가 무엇이든지 형제 곧 나그네 된 자들에게 행하는 것은 신실한 일이니
-6 그들이 교회 앞에서 너의 사랑을 증언하였느니라 네가 하나님께 합당하게 그들을 전송하면 좋으리로다
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

