3.반복단어 찾기(형광펜 추천)
예수 그리스도를부인하는 자(가만히 들어온 사람들/은혜를 도리어 방탕한 것으로 바꿈/믿지 아니하는 자들 ) : 4절.5절
육체를 따라/육체를 더럽히며: 7절  8절
비방하는도다:8절 10절
영원힌 불의 형벌/영원한 결박/ 멸망: 6절 7절 10절

4.주제만들기: 
믿지않는 자들이 받게될 심판

5.하나님 찾기 (관찰): 
사랑의 하나님
부르시는 하나님
믿지 아니하는자들을 멸하시는 하나닝

6.인간 찾기 (관찰)
믿음의 도를 위하여 힘써 싸우기
예수 그리스도를 부인하는 자
믿지 않음으로 최후에 멸망받을 자들

7.하나님 찾기 (해석)
사랑의 하나님은 모든사람들이 구윈받고 천국의 시민으로 살기를 원하신다. 하지만 죄의 본성에서 탈출하지 못하고 끝까지 회개하지 않고 세상에서 불의를 행하고 산다면 하나님은 공의로써 그들을 영원한 형벌의 심판으로 다스릴것이다.

8.인간(해석):
믿음의 공동체를 무너뜨리는 것은 사탄의 목표이고 마귀들이 지햠하는 것이다

그들이 접근할때는 급하게 다가오는것이 아니라 ''가만히'' 접근하는 전략을 알수있다 요즘 큰 물의를 일으키는 이단종교들 대부분이 교회나 성도를 미혹하거나 포교할때도 이러한 방법을 사용하는 것을 볼수있다

그러한 것으로 공동체나 개인의 영혼을 지키기 위해서는 3절의 기록말씀 "성도에게 단번예 주신 믿음의 도를 위하여 힘써 싸우라" 처럼 구원자이신 예수를 굳게 믿고 사는것이 온전한 진리임을 유다를 통하여 알수있다

사실 유다는 예수님의 육체적 동생이었고 처음에는 그도 믿음의 도를 잘 이해하지 못했으나 예수의 십자가 죽음 이후 부활예수를 만나고 믿음의 사람으로 거듭났음을 알수있다

영적으로 믿는다는 것이 얼마나 중요한지 알수있다 

9.적용(나):
믿음의 온전한 대상이신 예수를 더욱 바라고 의지해야겠다 

10. 영적터치(단어/구절)
3절: 믿음의 도를 위하여 힘써 싸우라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-18', '유다서', '1장 11절 ~ 20절', '&nbsp;', '(유다서 1장)
11. 화 있을진저 이 사람들이여, 가인의 길에 행하였으며 삯을 위하여 발람의 어그러진 길로 몰려 갔으며 고라의 패역을 따라 멸망을 받았도다
12. 그들은 기탄 없이 너희와 함께 먹으니 너희의 애찬에 암초요 자기 몸만 기르는 목자요 바람에 불려가는 물 없는 구름이요 죽고 또 죽어 뿌리까지 뽑힌 열매 없는 가을 나무요
13. 자기 수치의 거품을 뿜는 바다의 거친 물결이요 영원히 예비된 캄캄한 흑암으로 돌아갈 유리하는 별들이라
14. 아담의 칠대 손 에녹이 이 사람들에 대하여도 예언하여 이르되 보라 주께서 그 수만의 거룩한 자와 함께 임하셨나니
15. 이는 뭇 사람을 심판하사 모든 경건하지 않은 자가 경건하지 않게 행한 모든 경건하지 않은 일과 또 경건하지 않은 죄인들이 주를 거슬러 한 모든 완악한 말로 말미암아 그들을 정죄하려 하심이라 하였느니라
16. 이 사람들은 원망하는 자며 불만을 토하는 자며 그 정욕대로 행하는 자라 그 입으로 자랑하는 말을 하며 이익을 위하여 아첨하느니라
17.  사랑하는 자들아 너희는 우리 주 예수 그리스도의 사도들이 미리 한 말을 기억하라
18. 그들이 너희에게 말하기를 마지막 때에 자기의 경건하지 않은 정욕대로 행하며 조롱하는 자들이 있으리라 하였나니
19. 이 사람들은 분열을 일으키는 자며 육에 속한 자며 성령이 없는 자니라
20. 사랑하는 자들아 너희는 너희의 지극히 거룩한 믿음 위에 자신을 세우며 성령으로 기도하며

