- 승천하신 예수님은 세상을 심판하고 성도를 구원하시려고 구름을 타고 다시 오실 것임
- 하나님은 스스로 있는 자로서 
- 처음부터 계셨고 지금도 계시고 미래에도 계시는 전능한 분이심
- 이 계시는 환난과 고통 가운데 믿음을 지켜오던 성도들에게 큰 힘과 위로가 되었을 것

