4.주제 만들기: 처음 사랑, 처음 행위를 회복하라

5.하나님 찾기 (관찰)
- 에베소 교회를 향한 말씀을 요한에게 전하시는 예수님
- 에베소 교회가 처음 사랑을 버렸음을 책망하는 예수님
- 회개하고 처음 행위를 가지라 명하는 예수님
- 서머나 교회를 향한 말씀을 요한에게 전하시는 예수님
- 처음이자 마지막이요 죽었다가 다시 살아나신 예수님
- 앞으로 받게 될 고난과 환난에 대하여 말씀하시는 예수님

6.인간 찾기 (관찰)
- 성령에 감동되어 예수님의 말씀을 받는 사도 요한
- 말씀 안에서 믿음을 지키며 인내한 에베소 교회
- 그러나 처음 사랑을 버린 에베소 교회
- 서머나 교회가 환난과 궁핍을 당하고 있으나
- 실상은 부요함

7.하나님 찾기 (해석) 
- 말씀에 순종하여 믿음으로 사는 것이 중요함.
- 그러나 예수님을 사랑하는 것과 이웃을 사랑하는 마음이 식어서는 안 된다는 것을 알려주심
- 처음이자 마지막이며 죽었다가 부활하신 예수님. 
- 즉 하나님께서 서머나 교회의 환난과 궁핍을 지켜보고 계심
- 앞으로도 고난과 환난이 있다고 말씀하시며 
- 그러나 두려워하지 말고 죽도록 충성하라 말씀해 주심으로 
- 믿음과 힘을 부어 주시는 하나님

8.인간(해석): 
- 말씀에 순종하여 믿음으로 사는 것이 중요하지만,
- 하나님을 향한 사랑과 이웃을 사랑하는 마음이 식지 않았는지 점검해야 한다.
- 처음 행위, 하나님을 깊이 사랑할 때 했던 행위를 회복해야 한다.
- 서머나 교회는 믿음을 견고히 하시고 힘을 부어 주시는 주님의 말씀을 받고 
- 많은 위로와 격려가 되었을 것이다.

9.적용(나)
- 말씀을 보면 하나님을 사랑하는 마음이 식었는지 확인하는 방법은 
- 우리의 행위를 보는 것이다.
- 그렇다면 나는 처음 행위를 잃었다.
- 중심은 아니라고 나는 하나님을 가장 사랑한다고 스스로 강력히 주장하지만, 
- 그렇지 않음을 처음 행위가 증명해 준다.
- 어디서부터 떨어졌는가 생각해 보면, 
- 다른 것이 아니라 내 행위가 변한 것이 중요한 것을 알 수 있다.
- 행위가 멀어지면, 형식이 깨지면 마음도 깨지기 쉽다.
- 속히 처음 행위를 회복해야겠다.

10. 영적터치(단어/구절)  
  5   그러므로 어디서 떨어졌는지를 생각하고 회개하여 처음 행위를 가지라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-24', '요한계시록', '2장 11절 ~ 20절', '책망을 가장한 사랑', '[계2:11-20]
11 귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 자는 둘째 사망의 해를 받지 아니하리라
12 버가모 교회의 사자에게 편지하라 좌우에 날선 검을 가지신 이가 이르시되
13 네가 어디에 사는지를 내가 아노니 거기는 사탄의 권좌가 있는 데라 네가 내 이름을 굳게 잡아서 내 충성된 증인 안디바가 너희 가운데 곧 사탄이 사는 곳에서 죽임을 당할 때에도 나를 믿는 믿음을 저버리지 아니하였도다
14 그러나 네게 두어 가지 책망할 것이 있나니 거기 네게 발람의 교훈을 지키는 자들이 있도다 발람이 발락을 가르쳐 이스라엘 자손 앞에 걸림돌을 놓아 우상의 제물을 먹게 하였고 또 행음하게 하였느니라
15 이와 같이 네게도 니골라 당의 교훈을 지키는 자들이 있도다
16 그러므로 회개하라 그리하지 아니하면 내가 네게 속히 가서 내 입의 검으로 그들과 싸우리라
17 귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 그에게는 내가 감추었던 만나를 주고 또 흰 돌을 줄 터인데 그 돌 위에 새 이름을 기록한 것이 있나니 받는 자 밖에는 그 이름을 알 사람이 없느니라
18 두아디라 교회의 사자에게 편지하라 그 눈이 불꽃 같고 그 발이 빛난 주석과 같은 하나님의 아들이 이르시되
19 내가 네 사업과 사랑과 믿음과 섬김과 인내를 아노니 네 나중 행위가 처음 것보다 많도다
20 그러나 네게 책망할 일이 있노라 자칭 선지자라 하는 여자 이세벨을 네가 용납함이니 그가 내 종들을 가르쳐 꾀어 행음하게 하고 우상의 제물을 먹게 하는도다

