2024년 6월21일 요한계시록 2장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천
- 교훈(14,15절), 성령이 교회들에게 하시는 말씀을 들을지어다(11,17절), 행음(14,20절), 우상의 제물(14,20절), 검(12,16절)
4.주제만들기: 책망을 가장한 사랑
5.하나님 찾기 (관찰)
- 성령님이 교회에 말씀하심
- 버가모 교회에 좌우의 날선 검을 가지신 이가 말하심
- 두어가지 책망하심. 발람의 교훈을 지키는 자들이 있고, 니골라 당의 교훈을 지키는 자들이 함께 있다고 말하심
- 회개하라. 회개하지 아니하면 속히 가서 입의 검으로 싸우리라 말하심
- 이기는 자에게는 만나를 주고 흰 돌을 줄 것인데 돌 위에 새 이름을 기록하고 받는자만이 그 이름을 알 수 있다 말하심
- 두디아라 교회에 눈치 불꽃 같고 발이 빛난 주석과 같은 하나님의 아들이 이르시되 네 사업과 사랑과 믿음과 섬김과 인내를 알고 나중 행위가 처음 행위보다 나은 것을 알지만 책망할 것이 있다고 말하심
6.인간 찾기 (관찰)
- 이기는 자는 둘째 사망의 해를 받지 않음
- 버가로 교회는  발람의 교훈을 지키는 자들과 니골라 당의 교훈을 지키는 자들이 있음
- 두디아라 교회는 선지자라하는 이세벨을 용납하고 그가 종들 꾀어 행음하게 하고 우상의 제물을 먹게 함
7.하나님 찾기 (해석) 
- 하나님께선 성령님을 통해 우리를 보호하시고 회개하게 하시어 돌이킬 수 있는 기회를 주심
- 하나님은 우리에게 죄에 대한 말씀만 하시는 것이 아니라 칭찬을 통해 위로하고 격려하심
- 하나님께서 입의 검으로 악한 자들과 싸우신다고 말씀하셨는데, 말씀이 바로 서 있다면 발람의 교훈과 니골라의 교훈에 넘어가지 않았을 것이다. 우리의 연약함을 하나님의 능력으로 채워주셨다.
- 하나님의 사랑은 우리가 헤아릴 수 없음
- 하나님의 검으로 죄를 완전히 끊어버려야 함.
8.인간(해석):
- 하나님께선 우리가 거한 자리를 정확히 아신다. 그곳이 성령님과 함께하는 자리인지 사탄과 함께 하는 자리인지.
- 사랑과 믿음과 섬김과 인내가 있더라도 우리는 행음하는 것에 넘어질 수 있다.
9. 적용(나): 
- 내가 거하는 자리가 성령님께서 함께 하시는지 점검하고 기도해야겠다. 
- 우리는 언제라도 넘어질 수 있는 연약한 존재임을 알고 나의 연약함을 하나님께 의지하며 보호하시도록 기도해야겠다.
10. 영적터치(단어/구절)
- 14 그러나 네게 두어 가지 책망할 것이 있나니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-25', '요한계시록', '2장 21절 ~ 29절', '&nbsp;', '(요한계시록 2장)
21. 또 내가 그에게 회개할 기회를 주었으되 자기의 음행을 회개하고자 하지 아니하는도다
22. 볼지어다 내가 그를 침상에 던질 터이요 또 그와 더불어 간음하는 자들도 만일 그의 행위를 회개하지 아니하면 큰 환난 가운데에 던지고
23. 또 내가 사망으로 그의 자녀를 죽이리니 모든 교회가 나는 사람의 뜻과 마음을 살피는 자인 줄 알지라 내가 너희 각 사람의 행위대로 갚아 주리라
24. 두아디라에 남아 있어 이 교훈을 받지 아니하고 소위 사탄의 깊은 것을 알지 못하는 너희에게 말하노니 다른 짐으로 너희에게 지울 것은 없노라
25. 다만 너희에게 있는 것을 내가 올 때까지 굳게 잡으라
26. 이기는 자와 끝까지 내 일을 지키는 그에게 만국을 다스리는 권세를 주리니
27. 그가 철장을 가지고 그들을 다스려 질그릇 깨뜨리는 것과 같이 하리라 나도 내 아버지께 받은 것이 그러하니라
28. 내가 또 그에게 새벽 별을 주리라
29. 귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다

