4.주제만들기: 
 두아디라교회에게 회개하고 다시 믿음을 붙잡기를 원하시는 주님

5.하나님 찾기 (관찰): 
죄에 빠진 교회와 자녀에게 회개의 기회를 주시는 주님
회개치 않는 자들을 벌하시는 주님
고난가운데 끝까지 믿음을 지키는 자에게 권세를 주시는 주님

6.인간 찾기 (관찰)
죄에 빠진 두아다라 교회 성도

7.하나님 찾기(해석):
이세벨을 용납하므로 우상을 섬기고 음난의 죄에 빠진 두아다라 교회를 향하여 주님은 회개할것을 강력히 경고 하셨다

만약 회개하지 않는다면 큰 환난 가운데 던질것이라 말씀하신다

이것을 통하여 생각할수 있는 것은 성도들이 이 땅에서 누구나 겪고사는  어려움 즉 외로움과 고독 그리고 고난의 강도는, 회개치 앓고 받을 영원한 큰 환난에 비하면 굉장히 경미한 수준임이 틀림이 없다.  도리어 성도로써 체험하는 작은 고난을 잘참고 주님이 원하시는 방향대로 산다면 큰 축복을 은혜의 주님이 준비하고 계심을 알수있다.

그러한 주님이 뜻하시는 데로 사는 모든 성도들에게  만물을 다스리는 권세까지 주신다는 주님의 은혜가 있다는 것을 요한은 기록하고 있다

8.인간(해석):

9.적용(나):
끝까지 믿음을 붙잡고 사는 종이 되야겠다. 그러기 위해서는 하나님이 주신 사명을 잘 실천해야겠다.

