4.주제만들기: 
 사데 교회 와 빌라델비아 교회의 실상

5.하나님 찾기 (관찰): 
사데 교회는 사실상 죽은교회라 평가하시는 주님
빌라델비아 교회에 대하여 작은 능력으로도 말씀을 지킴으로 보호받을 것으로 위로하시는 주님

6.인간 찾기 (관찰)

7.하나님 찾기(해석):

8.인간(해석):
사데교회는 스스로 살았다 하나 실상은 죽은 교회이다.  반면 빌라델비아 교회는 작은 능력을 가졌지만 하나님의 말씀을 인내로 지킴으로 칭찬을 받는다.
칭찬을 받을뿐만 아니라 시험이 올때 주님이 지켜 주신다고 말씀하신다.

두교회를 통해서 느끼는 것은 모든 능력은 하나님께 있음을 확신할수있다. 스스로 작거나 생동감 있다고 해서 그것이 전부는 아니다는 것이다.

특별히 빌라델비아 교회는 주님이 인정할정도로 본래  능력이 없는 교회이다. 그럼에도 말씀을 지키니 큰 능력으로 지켜주심을 약속하신다.

나역시 다른사람보다 가진 능력이나 은사가 많이 부족해도 주님의 말씀을 끝까지 붙잡고 순종한다면 반드시 풍성한 열매를 맺게될것이다.

9.적용(나):
받은 능력과 관계없이 주님의 말씀을 굳게잡고 살아내야겠다 

10. 영적터치(단어/구절)
