2024년 6월 24일 요한계시록 3장 11절~22절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다(13,22절), 차지도, 뜨겁지도(15,16절), 이기는(21절)
4.주제만들기: 책망하여 회개시켜서라도 보좌에 앉길 원하시는 하나님
5.하나님 찾기 (관찰)
- 아멘이시고, 충성되고 참된 증인이시며, 하나님 창조의 근본이심 
- 불로 연단한 금을 사서 부요하게 하고, 흰 옷으로 벌거벗은 수치를 보지 않게 하며 안약을 사서 눈에 발라 보이게 하시는 주님
- 문 밖에 서서 두드리심, 음성을 듣고 문을 열면 들어와 그와 더불어 먹고 그는 하나님과 더불어 먹게 됨
- 이기는 자에게 예수님께서 세상을 이기시고 하나님 보좌에 앉으신 것 같이 해주심
6.인간 찾기 (관찰)
- 차지도 뜨겁지도 않은 상태의 인간(나)
- 듣지 않는 인간
7.하나님 찾기 (해석) 
- 하나님께서 얼마나 인간을 사랑하시는지 알 수 있다. 우리를 책망해서라도 회개하게 하고 세상과의 싸움에서 이겨 하나님께서 예비하신 보좌에 앉길 원하신다. 그 보좌는 예수님께서 십자가를 지시고 얻으신 보좌인데 우리는 이 땅에서 하나님께서 명하신 것들만 따르더라도 동일한 보좌를 얻을 수 있다. 
- 하나님께선 그 보좌를 얻는 길에 가만히 지켜만 보고 계시지 않는다. 불로 연단한 금을 준비하시고(훈련), 흰색 옷을 준비하시며(경건), 안약을 준비하셔서 진리를 바라보게 하신다. 
- 우리는 하나님께서 부르시는 음성을 듣고 그 문을 열어주기만 하면 된다.
8.인간(해석):
- 우리의 상태를 정확히 꿰 뚫는 하나님이시다. 차지도 뜨겁지도 않은 미지근한 상태. 하나님을 믿지만 아무것도 하지 않는 영적 상태. 깊은 회개와 하나님의 은혜가 필요하다.
9. 적용(나): 
- 회개하고, 하나님께서 예비하신 검과 옷과 약으로 세상을 이기는 삶을 살고싶다. 
- 노방전도, NKFC 사역에 더욱 힘쓰자. 우리가 하는 일을 하나님께서 매우 기뻐하신다.
10. 영적터치(단어/구절)
-19 무릇 내가 사랑하는 자를 책망하여 징계하노니 그러므로 네가 열심을 내라 회개하라
-20 볼지어다 내가 문 밖에 서서 두드리노니 누구든지 내 음성을 듣고 문을 열면 내가 그에게로 들어가 그와 더불어 먹고 그는 나와 더불어 먹으리라
-21 이기는 그에게는 내가 내 보좌에 함께 앉게 하여 주기를 내가 이기고 아버지 보좌에 함께 앉은 것과 같이 하리라
-22 귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-28', '요한계시록', '4장 1절 ~ 11절', '보좌에 앉으신 하나님', '요한계시록 4장
1   이 일 후에 내가 보니 하늘에 열린 문이 있는데 내가 들은 바 처음에 내게 말하던 나팔 소리 같은 그 음성이 이르되 이리로 올라오라 이 후에 마땅히 일어날 일들을 내가 네게 보이리라 하시더라
2   내가 곧 성령에 감동되었더니 보라 하늘에 보좌를 베풀었고 그 보좌 위에 앉으신 이가 있는데
3   앉으신 이의 모양이 벽옥과 홍보석 같고 또 무지개가 있어 보좌에 둘렸는데 그 모양이 녹보석 같더라
4   또 보좌에 둘려 이십사 보좌들이 있고 그 보좌들 위에 이십사 장로들이 흰 옷을 입고 머리에 금관을 쓰고 앉았더라
5   보좌로부터 번개와 음성과 우렛소리가 나고 보좌 앞에 켠 등불 일곱이 있으니 이는 하나님의 일곱 영이라
6   보좌 앞에 수정과 같은 유리 바다가 있고 보좌 가운데와 보좌 주위에 네 생물이 있는데 앞뒤에 눈들이 가득하더라
7   그 첫째 생물은 사자 같고 그 둘째 생물은 송아지 같고 그 셋째 생물은 얼굴이 사람 같고 그 넷째 생물은 날아가는 독수리 같은데
8   네 생물은 각각 여섯 날개를 가졌고 그 안과 주위에는 눈들이 가득하더라 그들이 밤낮 쉬지 않고 이르기를 거룩하다 거룩하다 거룩하다 주 하나님 곧 전능하신 이여 전에도 계셨고 이제도 계시고 장차 오실 이시라 하고
9   그 생물들이 보좌에 앉으사 세세토록 살아 계시는 이에게 영광과 존귀와 감사를 돌릴 때에
10   이십사 장로들이 보좌에 앉으신 이 앞에 엎드려 세세토록 살아 계시는 이에게 경배하고 자기의 관을 보좌 앞에 드리며 이르되
11   우리 주 하나님이여 영광과 존귀와 권능을 받으시는 것이 합당하오니 주께서 만물을 지으신지라 만물이 주의 뜻대로 있었고 또 지으심을 받았나이다 하더라

3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 6월 25일 요한계시록 4장 1~11절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하늘: 1, 2
보좌: 2(2), 3, 4(3), 5(2), 6(3), 9, 10(2)
앉으신: 2, 3
모양: 3(2)
이십사: 4(2), 10
장로: 4, 10
일곱: 5(2)
생물: 6, 7(4), 8, 9
눈들이 가득하더라: 6, 8
거룩하다: 8(3)
하나님: 8, 11
영광: 9, 11
존귀: 9, 11
