4.주제 만들기: 보좌에 앉으신 하나님

5.하나님 찾기 (관찰)
- 뒤에 일어날 일을 보여주려 요한에게 임하신 성령님
- 보좌에 앉으신 하나님
- 만물을 주의 뜻대로 창조하심

6.인간 찾기 (관찰)
- 성령에 감동되어 보좌에 앉으신 하나님의 영광과
- 보좌에서 하나님을 찬양하는 이십사 장로들과 네 생물을 목격하는 요한

7.하나님 찾기 (해석) 
- 뒤에 일어날 일을 보여주어, 성도들이 뒤에 일을 대비할 수 있도록 하시는 것
- 하나님은 빛나는 모습으로 보좌에 앉아 계심
- 만물을 창조하시되, 자기 뜻대로 창조하신 하나님은
- 영광과 존귀와 권능을 받으시는 것이 합당하신 분이다

8.인간(해석): 
- 보좌에 앉으신 하나님과
- 이십사 장로와 네 생물을 바라보며
- 그리고 그들이 하나님을 경배하는 모습을 보며
- 하나님께서 얼마나 위대하시고,
- 찬양 받기에 합당하신 분이신지
- 절실히 느꼈을 것

9.적용(나)
- 나는 하나님이 얼마나 위대하시며
- 얼마나 아름다우시며
- 얼마나 광대하신지 알지 못한다.
- 그러나 그 위대하심과 아름다우심과 광대하심을 조금씩 조금씩 더 누리고 싶다.
- 주님의 초대에 응하여 주님과 더불어 먹고 마시며(말씀과 기도 생활을 충실히 하며),
- 주님의 아름다움을 만끽하고 싶다.

10. 영적터치(단어/구절)  
  11   우리 주 하나님이여 영광과 존귀와 권능을 받으시는 것이 합당하오니 주께서 만물을 지으신지라 만물이 주의 뜻대로 있었고 또 지으심을 받았나이다 하더라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-29', '요한계시록', '5장 1절 ~ 14절', '&nbsp;', '(요한계시록 5장)
1.  내가 보매 보좌에 앉으신 이의 오른손에 두루마리가 있으니 안팎으로 썼고 일곱 인으로 봉하였더라
2. 또 보매 힘있는 천사가 큰 음성으로 외치기를 누가 그 두루마리를 펴며 그 인을 떼기에 합당하냐 하나
3. 하늘 위에나 땅 위에나 땅 아래에 능히 그 두루마리를 펴거나 보거나 할 자가 없더라
4. 그 두루마리를 펴거나 보거나 하기에 합당한 자가 보이지 아니하기로 내가 크게 울었더니
5. 장로 중의 한 사람이 내게 말하되 울지 말라 유대 지파의 사자 다윗의 뿌리가 이겼으니 그 두루마리와 그 일곱 인을 떼시리라 하더라
6. 내가 또 보니 보좌와 네 생물과 장로들 사이에 한 어린 양이 서 있는데 일찍이 죽임을 당한 것 같더라 그에게 일곱 뿔과 일곱 눈이 있으니 이 눈들은 온 땅에 보내심을 받은 하나님의 일곱 영이더라
7. 그 어린 양이 나아와서 보좌에 앉으신 이의 오른손에서 두루마리를 취하시니라
8. 그 두루마리를 취하시매 네 생물과 이십사 장로들이 그 어린 양 앞에 엎드려 각각 거문고와 향이 가득한 금 대접을 가졌으니 이 향은 성도의 기도들이라
9. 그들이 새 노래를 불러 이르되 두루마리를 가지시고 그 인봉을 떼기에 합당하시도다 일찍이 죽임을 당하사 각 족속과 방언과 백성과 나라 가운데에서 사람들을 피로 사서 하나님께 드리시고
10. 그들로 우리 하나님 앞에서 나라와 제사장들을 삼으셨으니 그들이 땅에서 왕 노릇 하리로다 하더라
11. 내가 또 보고 들으매 보좌와 생물들과 장로들을 둘러 선 많은 천사의 음성이 있으니 그 수가 만만이요 천천이라
12. 큰 음성으로 이르되 죽임을 당하신 어린 양은 능력과 부와 지혜와 힘과 존귀와 영광과 찬송을 받으시기에 합당하도다 하더라
13. 내가 또 들으니 하늘 위에와 땅 위에와 땅 아래와 바다 위에와 또 그 가운데 모든 피조물이 이르되 보좌에 앉으신 이와 어린 양에게 찬송과 존귀와 영광과 권능을 세세토록 돌릴지어다 하니
14. 네 생물이 이르되 아멘 하고 장로들은 엎드려 경배하더라

3331 생명의 큐티
