INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-06-30', '요한계시록', '6장 1절 ~ 10절', '봉인을 떼시는 예수님', '요한계시록 6장
1   내가 보매 어린 양이 일곱 인 중의 하나를 떼시는데 그 때에 내가 들으니 네 생물 중의 하나가 우렛소리 같이 말하되 오라 하기로
2   이에 내가 보니 흰 말이 있는데 그 탄 자가 활을 가졌고 면류관을 받고 나아가서 이기고 또 이기려고 하더라
3   둘째 인을 떼실 때에 내가 들으니 둘째 생물이 말하되 오라 하니
4   이에 다른 붉은 말이 나오더라 그 탄 자가 허락을 받아 땅에서 화평을 제하여 버리며 서로 죽이게 하고 또 큰 칼을 받았더라
5   셋째 인을 떼실 때에 내가 들으니 셋째 생물이 말하되 오라 하기로 내가 보니 검은 말이 나오는데 그 탄 자가 손에 저울을 가졌더라
6   내가 네 생물 사이로부터 나는 듯한 음성을 들으니 이르되 한 1)데나리온에 밀 한 되요 한 1)데나리온에 보리 석 되로다 또 감람유와 포도주는 해치지 말라 하더라
7   넷째 인을 떼실 때에 내가 넷째 생물의 음성을 들으니 말하되 오라 하기로
8   내가 보매 청황색 말이 나오는데 그 탄 자의 이름은 사망이니 음부가 그 뒤를 따르더라 그들이 땅 사분의 일의 권세를 얻어 검과 흉년과 사망과 땅의 짐승들로써 죽이더라
9   다섯째 인을 떼실 때에 내가 보니 하나님의 말씀과 그들이 가진 증거로 말미암아 죽임을 당한 영혼들이 제단 아래에 있어
10   큰 소리로 불러 이르되 거룩하고 참되신 대주재여 땅에 거하는 자들을 심판하여 우리 피를 갚아 주지 아니하시기를 어느 때까지 하시려 하나이까 하니

