4.주제 만들기: 봉인을 떼시는 예수님

5.하나님 찾기 (관찰)
- 봉인을 떼시는 예수님

6.인간 찾기 (관찰)
- 환상을 보는 사도 요한
- 땅에 거하는 자들을 심판하여 우리 피를 갚아 주지 아니하시기를 어느 때까지 하시려 하나이까 부르짖는 죽임 당한 사람들의 영혼

7.하나님 찾기 (해석) 
- 봉인을 떼기에 합당하신 어린 양 예수님
- 예수님 일곱 봉인을 하나씩 떼어내실 것이다.

8.인간(해석): 
- 봉인이 떼어지는 시기와 그 결과는 알 수 없지만,
- 이 봉인이 떼어지는 시기가 하루씩 더 다가오는 것은 알 수 있다.  

9.적용(나)
- 어린 양 예수님께서 하나님의 말씀과 그들이 가진 증거로 말미암아 죽임을 당한 영혼들의 부르짖음을 듣고 계시며, 살아있는 신자들의 부르짖음도 듣고 계신다.
- 예수님께서는 일곱 봉인도 떼실 것이며 다시 이 땅에 오실 것이다.
- 예수님께서 이루신 최후 승리를 바라보며, 
- 고단한 나그네 인생길, 힘을 내어 살아가야 한다.

