INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-01', '요한계시록', '6장 11절 ~ 17절', '피할 수 없는 진노의 날', '[계6:11-17]
11 각각 그들에게 흰 두루마기를 주시며 이르시되 아직 잠시 동안 쉬되 그들의 동무 종들과 형제들도 자기처럼 죽임을 당하여 그 수가 차기까지 하라 하시더라
12 내가 보니 여섯째 인을 떼실 때에 큰 지진이 나며 해가 검은 털로 짠 상복 같이 검어지고 달은 온통 피 같이 되며
13 하늘의 별들이 무화과나무가 대풍에 흔들려 설익은 열매가 떨어지는 것 같이 땅에 떨어지며
14 하늘은 두루마리가 말리는 것 같이 떠나가고 각 산과 섬이 제 자리에서 옮겨지매
15 땅의 임금들과 왕족들과 장군들과 부자들과 강한 자들과 모든 종과 자유인이 굴과 산들의 바위 틈에 숨어
16 산들과 바위에게 말하되 우리 위에 떨어져 보좌에 앉으신 이의 얼굴에서와 그 어린 양의 진노에서 우리를 가리라
17 그들의 진노의 큰 날이 이르렀으니 누가 능히 서리요 하더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
