2024년 6월 28일 요한계시록 6장 11절~17절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 진노(16,17절)
4.주제만들기: 피할 수 없는 진노의 날
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 땅의 임금들과 왕족들과 장군들과 부자들과 강한 자들과 모든 종과 자유인이 굴과 산과 바위 틈에 숨어 보좌에 앉으신 이의 얼굴과 어린 양의 진노에서 가려주길 요청함
7.하나님 찾기 (해석) 
8.인간(해석):
- 하나님의 때, 하나님의 심판의 날을 인간은 알지 못한다. 그 날이 되어도 인간은 하나님 앞에 엎드릴 용기와 죄 고백을 하지 못한다. 그저 진노를 피하기 위해 산과 바위에 숨기만 할 뿐이다. 
- 나의 죄를 알게 되었을 때 하나님 앞에 나아가 죄를 고백하는 것이 중요하다. 그런데 고백마저도 하나님의 은혜가 아니라면 깨닫 것과 고백하는 것과 결단하는 것을 행할 수 없다.
- 삶을 살아가면서 기쁠 때가 있고 슬플 때도 있으며, 고난과 같이 느껴지는 힘든 상황도 있다. 모든 상황이 감사한 것은 하나님과 동행할 수 있다는 것이다. 때로는 고난이 나의 죄성을 없앨 수 있는 좋은 훈련의 기간이 된다.
9. 적용(나): 
- 나의 죄를 깨닫게 하신 하나님께 감사하다. 아직 알지 못하는 죄가 있다면 깨닫길 원하며 하나님 앞에 엎드려 회개 한다. 
- 하나님의 때가 이르기 전에 노방전도에 더욱 힘써야겠다. 한 영혼이라도 전하지 못하면 아쉬움이 가득한 마음이 내 안에 생기길 원한다.
10. 영적터치(단어/구절)
- 16 산들과 바위에게 말하되 우리 위에 떨어져 보좌에 앉으신 이의 얼굴에서와 그 어린 양의 진노에서 우리를 가리라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-02', '요한계시록', '7장 1절 ~ 10절', '&nbsp;', '(요한계시록 7장)
1.  이 일 후에 내가 네 천사가 땅 네 모퉁이에 선 것을 보니 땅의 사방의 바람을 붙잡아 바람으로 하여금 땅에나 바다에나 각종 나무에 불지 못하게 하더라
2. 또 보매 다른 천사가 살아 계신 하나님의 인을 가지고 해 돋는 데로부터 올라와서 땅과 바다를 해롭게 할 권세를 받은 네 천사를 향하여 큰 소리로 외쳐
3. 이르되 우리가 우리 하나님의 종들의 이마에 인치기까지 땅이나 바다나 나무들을 해하지 말라 하더라
4. 내가 인침을 받은 자의 수를 들으니 이스라엘 자손의 각 지파 중에서 인침을 받은 자들이 십사만 사천이니
5.  유다 지파 중에 인침을 받은 자가 일만 이천이요 르우벤 지파 중에 일만 이천이요 갓 지파 중에 일만 이천이요
6. 아셀 지파 중에 일만 이천이요 납달리 지파 중에 일만 이천이요 므낫세 지파 중에 일만 이천이요
7. 시므온 지파 중에 일만 이천이요 레위 지파 중에 일만 이천이요 잇사갈 지파 중에 일만 이천이요
8. 스불론 지파 중에 일만 이천이요 요셉 지파 중에 일만 이천이요 베냐민 지파 중에 인침을 받은 자가 일만 이천이라
9. 이 일 후에 내가 보니 각 나라와 족속과 백성과 방언에서 아무도 능히 셀 수 없는 큰 무리가 나와 흰 옷을 입고 손에 종려 가지를 들고 보좌 앞과 어린 양 앞에 서서
10. 큰 소리로 외쳐 이르되 구원하심이 보좌에 앉으신 우리 하나님과 어린 양에게 있도다 하니

