7.하나님 찾기(해석):
 큰 환난에서 나오는 자들의 옷을 어린양 예수의 피로 씻어 희게 하셨다

세상 가운데 각종 고난을 겪은 성도들의  상처받은 옷의 얼룩들은 색깔과 크기 그리고 아픔과 고통의 깊이는 모두 다를것이다.

그럼에도 어린양 예수 의 피로 모든것이 해결되며 모든것이 하얀 눈 처럼 하얗게 변하는 능력을 행하신다 하신다

8.인간(해석):
세상의 풍파와 고통이 아무리 크게 다가오더라도 주님을 의지하고 인내하면 반드시 좋은때가 올거라 요한은 보고 들은것을 알려주고 있다

''다시는 주리지도 아니하며 목마르지도 아니하고 해나 아무 뜨거운 기운에 상하지도 아니하리니''

얼마나 기대되는 세상인가?
이세상에서 결코 지속적으로 가질수 없는 천국!!
어린양 예수의 십자가 사랑에 더욱 감사할수 밖에 없다!!

9.적용(나):
영원한 천국 소망을 더욱  바라며 아울러 어린양 예수의 흘리신 보혈의 사랑의 의미를 더욱 묵상해야겠다 

