- 천사들의 나팔이 3개 남아있음
6.인간 찾기 (관찰)
- 고난과 어둠 가운데서도 기도하는 성도들
7.하나님 찾기 (해석) 
- 하나님은 우리를 사랑하시고 우리가 돌이키길 원하신다. 하나님께선 단번에 이 세상을 없애실 수 있지만 7번의 나팔을 사용해 인간에게 회개하고 돌이킬 수 있는 기회를 주신다. 
8.인간(해석):
- 성도들의 기도가 합하여 하나님께 전달되었다는 것은 악한 세상 가운데서 중심을 잃지 않고 있는 성도들이 있다는 사실을 깨닫게 하며 소망을 갖게 된다. 성도의 기도로 하나님께서는 다시금 돌이킬 수 있는 사인을 주신다. 이 모든 것은 우리가 세상과 하나님이 예비하실 영혼을 위해 기도하는 소망이 된다. 하나님께서는 우리의 기도를 듣고 계신다.
9. 적용(나): 
- 기도로 말씀으로 행동으로 우리는 어둠 가운데 있는 사람들을 구원의 길로 인도해야 한다. 
- 하나님께서 기회를 주실 때 전도에 더욱 힘써야겠다.
10. 영적터치(단어/구절)
- 4 향연이 성도의 기도와 함께 천사의 손으로부터 하나님 앞으로 올라가는지라
11. 믿음과 회개 및 감사기도로 마무리
