- 하나님은 창조주이시며 영원한 분으로서 찬양받기에 합당하신 분이다.
- 일곱째 천사가 불려고 하는 나팔 소리가 나는 날에는, 
- 하나님께서 하나님의 종 예언자들에게 전하여 주신 대로, 
- 하나님의 비밀이 이루어질 것이다.

8. 인간 찾기 (해석)
- 천사가 말한 것을 기록하지 못하게 한 것으로 보아,
- 하나님의 뜻과 계획 중에는 사람이 알아야 할 것이 있고,
- 사람이 알아서는 안 되는 내용이 있다.
- 두루마리의 맛은 달겠지만, 배에는 쓸 것이라는 천사의 말이 이루어지는 것을 경험함.
- 그리고 다시 예언해야 한다는 음성을 듣게 됨.
- 이런 경험들을 통해 요한은 일들이 반드시 이루어질 것이라는 확신이 들었을 것임. 

9. 적용(나) 
- 일곱째 천사가 나팔을 불 때에 하나님의 비밀이 이루어질 것과
- 하나님의 계획이 완성되는 날이 올 것을 믿는다.
- 세상 속에서 살아가는 것이 만만치 않지만,
- 성령 안에서 그날을 바라보며 나에게 주어진 길을 묵묵히 걸어가야겠다.

10. 영적 터치(단어/구절)
  7 하나님의 그 비밀이 이루어지리라 하더라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

