4.주제만들기: 악을 이기시는 하나님
5.하나님 찾기 (관찰)
- 하나님의 성전과 제단과 경배하는 자들을 측량하심
- 성전 바깥 마당은 측량치 않으시고 두심
- 두 증인에게 권세를 주어 예언하게 하심
- 그들이 증언을 마칠 때 무저갱에서 올라오는 짐승과의 전쟁에서 승리케하심
6.인간 찾기 (관찰)
7.하나님 찾기 (해석) 
- 하나님께서는 성전 밖에 있는 악한 자들을 그대로 두신다. 악한 자들을 방치하는 것이 아니라 최후의 날에 그들을 심판하기 위해 두시는 것이다. 개인이 가지고 있는 악한 죄성이 씨앗이 되어 성전 밖으로 이끌 수 있다. 성전 밖에 나오는 순간 하나님과 멀어지며 죄의 삯은 사망이듯 심판을 받게 될 것이다. 
- 그러나 하나님 안에 거하는 자들은 하나님의 전적인 보호를 받는다. 갈대로 측량을 하는데 치밀하게 측정하지 않으면 온전히 보호하지 못하기 때문이란 생각이 들었다. 측량이 잘못되면 건축물에 문제가 생기듯이 완벽한 측량 없이 건축물과 그 안에 거주하는 사람들이 보호받지 못할 것이다. 악은 성전을 무너뜨릴 만큼 위협적이지만 하나님의 보호하심은 우리를 완벽히 지켜주신다. 
- 하나님 안에 거하며 하나님의 보호를 받고 있으면 하나님께서 악을 물리치시고 승리로 이끄신다. 우리는 하나님 안에 거하기만 하면 된다. 쉽지만 어려운 일이기 때문에 하나님의 은혜를 구해야한다.
